		"A colour of my own" => "צבע משלי",
		"A colour, a size, a length. One product, several versions of it — each with its own stock and, if you like, its own price." => "צבע, מידה, אורך. מוצר אחד, כמה גרסאות שלו — לכל אחת מלאי משלה, ואם תרצו גם מחיר משלה.",
		"A complete policy in the site's language with the shop's name and contact details filled in, the live cookie table, and a form for data requests. It covers the Israeli Protection of Privacy Law (including the Amendment 13 notice at collection) and the GDPR for European visitors. Read it once before launch — a lawyer should confirm anything specific to your business." => "מדיניות מלאה בשפת האתר עם שם החנות ופרטי הקשר ממולאים, טבלת העוגיות החיה, וטופס לבקשות מידע. היא מכסה את חוק הגנת הפרטיות הישראלי (כולל הודעת סעיף 11 לפי תיקון 13) ואת ה-GDPR למבקרים מאירופה. קראו אותה פעם אחת לפני העלייה לאוויר - עורך דין צריך לאשר כל דבר ספציפי לעסק שלכם.",
		"A contact card on the product page?" => "כרטיס יצירת קשר בעמוד המוצר?",
		"A content area" => "אזור תוכן",
		"A content area is a few words and a picture, standing between the shelves: your story, a promise, a collection. One block of questions for each one you kept." => "אזור תוכן הוא כמה מילים ותמונה, שעומדים בין המדפים: הסיפור שלכם, הבטחה, קולקציה. יש כאן בלוק שאלות אחד לכל אזור ששמרתם.",
		"A coupon field in the panel?" => "שדה קופון בחלונית?",
		"A custom logo (upload below)" => "לוגו מותאם (העלאה למטה)",
		"A daily report, every morning" => "דוח יומי, כל בוקר",
		"A dark veil over the image so light text stays readable. 0 = off." => "צעיף כהה מעל התמונה כדי שטקסט בהיר יישאר קריא. 0 = כבוי.",
		"A delivery and returns tab on every product?" => "לשונית משלוחים והחזרות בכל מוצר?",
		"A department — Sofas, Lighting, Dining" => "מחלקה — ספות, תאורה, פינות אוכל",
		"A different handful each time" => "קומץ אחר בכל פעם",
		"A different number" => "מספר אחר",
		"A discount" => "הנחה",
		"A face, a name and a button that opens WhatsApp or dials. On goods people hesitate over it is often what settles it." => "פנים, שם וכפתור שפותח וואטסאפ או מחייג. במוצרים שמתלבטים עליהם זה לא פעם מה שסוגר את העסקה.",
		"A facet built from main categories — e.g. a \"Gender\" group holding the Women and Men categories. Filtering shows the current category's products that also belong to the chosen one." => "פילטר שנבנה מקטגוריות ראשיות — למשל קבוצת \"מגדר\" שמכילה את הקטגוריות נשים וגברים. הסינון מציג את מוצרי הקטגוריה הנוכחית שמשויכים גם לקטגוריה שנבחרה.",
		"A fade in a colour of my own" => "דעיכה בצבע משלי",
		"A feed is the file a network reads to know what you sell. Choose who it is for, give it a name, and everything else already carries the setting that suits a shop. Each feed has one address that never changes and always answers with the newest build." => "פיד הוא הקובץ שרשת קוראת כדי לדעת מה אתם מוכרים. בוחרים למי הוא, נותנים לו שם, וכל השאר כבר מוגדר במה שנכון לחנות. לכל פיד יש כתובת אחת שלא משתנה, והיא תמיד מחזירה את הבנייה האחרונה.",
		"A few" => "מעט",
		"A few lines" => "כמה שורות",
		"A few lines about who you are. This becomes the About page and the short text on the home page." => "כמה שורות על מי אתם. זה הופך לעמוד האודות ולטקסט הקצר בעמוד הבית.",
		"A few points about the business" => "כמה נקודות על העסק",
		"A few products, straight from the shop" => "כמה מוצרים, ישירות מהחנות",
		"A few required fields are still empty." => "כמה שדות חובה עדיין ריקים.",
		"A few words about the experience?" => "כמה מילים על החוויה?",
		"A finger-swipe strip that runs to the screen edge — below the hero or with its text." => "רצועת החלקה שרצה עד קצה המסך — מתחת לבאנר או יחד עם הטקסט שלו.",
		"A full URL or a relative path; a trailing * makes a prefix rule. The target field searches the site as you type." => "כתובת מלאה או נתיב יחסי; * בסוף יוצרת כלל תחילית. שדה היעד מחפש באתר תוך כדי הקלדה.",
		"A gift" => "מתנה",
		"A gift for a friend" => "מתנה לחבר",
		"A gift, or an order sent to the office. The buyer fills in a different address and name." => "מתנה, או הזמנה שנשלחת למשרד. הקונה ממלא כתובת ושם אחרים.",
		"A green dot while someone is there" => "עיגול ירוק כשמישהו זמין",
		"A grid" => "גריד",
		"A half-typed word is never offered back: \"שול\" counts towards \"שולחן\" and the finished word is what appears." => "מילה חצי־מוקלדת לא תוצג: ״שול״ נספר לטובת ״שולחן״, והמילה השלמה היא שמופיעה.",
		"A heading and a list under it" => "כותרת ורשימה מתחתיה",
		"A heading and words" => "כותרת וטקסט",
		"A line about this branch" => "שורה על הסניף הזה",
		"A line about what you sell and for whom." => "שורה על מה אתם מוכרים ולמי.",
		"A line above the button saying how the stock is?" => "שורה מעל הכפתור שמספרת על המלאי?",
		"A line draws itself" => "קו שמצייר את עצמו",
		"A line of description under the name?" => "שורת תיאור מתחת לשם?",
		"A line of messages running across" => "פס מסרים רץ",
		"A line slides through" => "קו שחולף",
		"A line that says how much more is needed. Only worth it if you offer free delivery over an amount." => "שורה שאומרת כמה עוד חסר. שווה רק אם יש אצלכם משלוח חינם מעל סכום.",
		"A line under it" => "שורה מתחתיה",
		"A line under the headline" => "שורה מתחת לכותרת",
		"A list of names" => "רשימת שמות",
		"A list to open" => "רשימה נפתחת",
		"A listing where every card is the same size reads as a spreadsheet. These rules apply to the shop and to every category that has not set its own." => "רשימה שבה כל הכרטיסים באותו גודל נקראת כמו גיליון אקסל. הכללים האלה חלים על החנות ועל כל קטגוריה שלא הגדירה לעצמה.",
		"A lobby shows the page chosen in “Lobby page” — no products, no filters." => "דף לובי מציג את העמוד שנבחר ב״עמוד לובי״ — בלי מוצרים ובלי סינון.",
		"A longer list continues in a second column standing close beside it." => "רשימה ארוכה יותר ממשיכה בעמודה שנייה צמודה לצדה.",
		"A lot" => "הרבה",
		"A name, a valid email and a phone are all needed." => "צריך שם, מייל תקין וטלפון.",
		"A new address" => "כתובת חדשה",
		"A one-question satisfaction survey?" => "סקר שביעות רצון של שאלה אחת?",
		"A panel with suggestions" => "פאנל עם הצעות",
		"A password can be reused, guessed or phished. With this on, the password gets you half way in and a code sent to the phone on the account finishes the job — so taking the shop needs the password and the handset. If the text cannot be sent the code goes to the account's e-mail instead, so a provider outage slows a sign-in rather than locking anyone out." => "סיסמא אפשר לנחש, לגנוב בפישינג, או שהיא חוזרת על סיסמא מאתר אחר שנפרץ. כשזה דלוק, הסיסמא מכניסה חצי דרך וקוד שנשלח לטלפון שרשום בחשבון משלים את השאר — כדי להשתלט על החנות צריך גם את הסיסמא וגם את המכשיר. אם לא ניתן לשלוח SMS, הקוד נשלח למייל של החשבון — כך שתקלה אצל ספק ה-SMS מאטה התחברות במקום לנעול מישהו בחוץ.",
		"A person to ask, right on the product page: a face, a name, and one button — WhatsApp with the message already written, or a call." => "מישהו לשאול, ממש בדף המוצר: פנים, שם וכפתור אחד. וואטסאפ עם הודעה כתובה מראש, או שיחה.",
		"A phone follows the desktop size unless you choose otherwise. A phone shows two columns, so \"2 columns\" fills its width." => "במובייל האריח מוצג לפי הגדרת הדסקטופ, אלא אם בוחרים אחרת. במובייל יש שתי עמודות, ולכן \"2 עמודות\" ממלא את כל הרוחב.",
		"A phone’s hero has little room; below it is usually the better place." => "בבאנר של טלפון אין הרבה מקום; מתחתיו זה בדרך כלל המקום הנכון.",
		"A photograph of the real thing, where several of your products stand together. A visitor presses what they like on it and reaches the product." => "תמונה אמיתית שבה כמה מהמוצרים שלכם עומדים יחד. הגולש לוחץ על מה שמצא חן בעיניו ומגיע למוצר.",
		"A photograph of them" => "תמונה שלו או שלה",
		"A picture" => "תמונה",
		"A picture across the whole width" => "תמונה לכל הרוחב",
		"A picture at the top of this category, with its name and description. How it looks is set once for every category in Customize › Catalogue page › Category hero." => "תמונה בראש הקטגוריה, עם השם והתיאור שלה. העיצוב נקבע פעם אחת לכל הקטגוריות בהתאמה אישית › עמוד קטלוג › באנר קטגוריה.",
		"A picture for the About page" => "תמונה לעמוד האודות",
		"A picture of the branch" => "תמונה של הסניף",
		"A picture that does not match the uniform frame" => "תמונה שלא בפרופורציה של המסגרת האחידה",
		"A picture, with words on it if you like" => "תמונה, ואם רוצים גם טקסט עליה",
		"A product filed under a sub-category, its parent and a shelf like NEW pulls neighbours from all three, and the loosest one wins. The narrow setting keeps only the most specific category — and falls back to what it has if there is nothing deeper." => "מוצר שמשויך לתת-קטגוריה, לקטגוריית האב שלה ולמדף כמו NEW שואב מוצרים משלושתן, והרחבה מנצחת. האפשרות המצומצמת שומרת רק על הקטגוריה הספציפית ביותר — ואם אין עמוקה יותר, נשארת עם מה שיש.",
		"A product sits in several categories at once — its own, its parent, and shelves like NEW. WooCommerce draws neighbours from all of them, so the loosest wins. The second option uses the single category shown in the product's path: for Sofas and armchairs / Sofas, that is Sofas. The third scores every product that shares a category on what it shares with this one — the categories (a deep one counts more), the words in the name, the price, tags and attribute values — so a 30-litre kitchen bin gets other large bins and a 3-litre bathroom bin gets small ones, with nothing to fill in." => "מוצר יושב בכמה קטגוריות בבת אחת: שלו, של ההורה, ומדפים כמו חדש. ווקומרס שואב שכנים מכולן, ולכן הרופפת ביותר מנצחת. האפשרות השנייה משתמשת בקטגוריה היחידה שמופיעה בנתיב המוצר: עבור ספות וכורסאות / ספות, זו ספות. השלישית מדרגת כל מוצר שחולק קטגוריה לפי מה שמשותף לו עם המוצר הזה: הקטגוריות (עמוקה שווה יותר), המילים בשם, המחיר, התגיות וערכי המאפיינים. כך פח מטבח 30 ליטר מקבל פחים גדולים אחרים ופח אמבטיה 3 ליטר מקבל קטנים, בלי למלא דבר.",
		"A promise" => "הבטחה",
		"A quantity box beside the buy button?" => "תיבת כמות ליד כפתור הקנייה?",
		"A ready-made footer preset — pick it, then fill the blanks. Link columns are menus (Appearance → Menus → assign to \"Footer column 1–4\"); each column's heading is set below. The bottom bar uses the \"Footer menu\" for its legal links." => "פוטר מוכן — בוחרים אותו וממלאים את החסר. עמודות הקישורים הן תפריטים (עיצוב ← תפריטים ← שיבוץ ל\"עמודת פוטר 1–4\"); הכותרת של כל עמודה נקבעת למטה. השורה התחתונה משתמשת ב\"תפריט הפוטר\" לקישורים המשפטיים.",
		"A real face does more here than a logo. It is cropped to a circle." => "פנים אמיתיות עובדות כאן יותר מלוגו. התמונה תיחתך לעיגול.",
		"A rebuild runs in batches, so a shop of any size finishes without a timeout. Search keeps working from the words already held while it runs." => "הבנייה רצה במנות, כך שחנות בכל גודל מסיימת בלי תקיעה. החיפוש ממשיך לעבוד מהמילים הקיימות בזמן שהיא רצה.",
		"A recognised number gets a code; a new one opens an account once" => "מספר מזוהה מקבל קוד; מספר חדש פותח חשבון פעם אחת",
		"A reminder: the questionnaire for your new store" => "תזכורת: השאלון לחנות החדשה שלכם",
		"A result looks like" => "תוצאה נראית כמו",
		"A row holds about seven as cards and four as rows, so pick a number that fills its rows rather than leaving one short." => "שורה מכילה בערך שבעה ככרטיסים וארבעה כשורות, אז בחרו מספר שממלא את השורות ולא משאיר אחת חסרה.",
		"A row of brands" => "שורת מותגים",
		"A row of products" => "סליידר מוצרים",
		"A row with no picture never gets shorter than this. When any link carries a picture, bare rows match the picture height instead, so the list stays even." => "שורה בלי תמונה לא תרד מתחת לגובה הזה. כשלפחות קישור אחד נושא תמונה, שורות בלי תמונה מיישרות לגובה התמונה — כדי שהרשימה תישאר אחידה.",
		"A row — picture beside the words" => "שורה — תמונה לצד הטקסט",
		"A rule filled in once per site — \"/women/ becomes /clothes/\" — applies to the address and to everything beneath it, on every run." => "כלל שממלאים פעם אחת לאתר — \"‎/women/ הופך ל-‎/clothes/\" — חל על הכתובת ועל כל מה שמתחתיה, בכל הרצה.",
		"A rule pointing at itself would spin forever." => "כלל שמצביע על עצמו יסתובב לנצח.",
		"A safe purchase" => "קנייה בטוחה",
		"A scan is running in the background…" => "סריקה רצה ברקע…",
		"A screen of its own, with a way back" => "מסך משלה, עם דרך חזרה",
		"A secure purchase" => "קנייה מאובטחת",
		"A shelf of products on this category page — best sellers, on sale, recently viewed, and more." => "מדף מוצרים בעמוד הקטגוריה — רבי-מכר, במבצע, מוצרים שצפית בהם, ועוד.",
		"A shopper who chooses collection picks the branch to collect from. Untick to leave this one out." => "לקוח שבוחר איסוף עצמי בוחר מאיזה סניף לאסוף. הסירו את הסימון כדי להשמיט את הסניף הזה.",
		"A shopper's own unpaid order never blocks them from ordering again" => "הזמנה שלא שולמה של הלקוח לעולם לא חוסמת אותו מלהזמין שוב",
		"A short film" => "סרטון קצר",
		"A short line about the product" => "שורת תיאור קצרה על המוצר",
		"A short line under the order details — what to do if something needs changing, for instance. Leave it empty and it does not appear." => "שורה קצרה מתחת לפרטי ההזמנה — למשל מה לעשות אם צריך לשנות משהו. השאירו ריק והיא לא תופיע.",
		"A site setting" => "הגדרה באתר",
		"A sketch of the page — it changes as you answer" => "סקיצה של העמוד — היא משתנה לפי התשובות",
		"A slider" => "סליידר",
		"A slider across" => "סליידר לרוחב",
		"A small card in a corner" => "כרטיס קטן בפינה",
		"A small floating badge" => "תג צף קטן",
		"A small line above" => "שורה קטנה מעל",
		"A small picture, no gallery" => "תמונה קטנה, בלי גלריה",
		"A small square picture, better with a see-through background. It stands in place of the one above." => "תמונה קטנה ומרובעת, עדיף עם רקע שקוף. היא תעמוד במקום זו שלמעלה.",
		"A story that unrolls as you scroll" => "תוכן נגלל",
		"A street and house number are needed." => "יש להזין רחוב ומספר בית.",
		"A strip above the header: how it looks and behaves. The messages themselves are written under Theme settings → Announcement bar." => "רצועה מעל ההדר: איך היא נראית ומתנהגת. את ההודעות עצמן כותבים תחת ״הגדרות תבנית ← בר הודעות״.",
		"A strip above the header: rotating messages in the centre, an optional side menu (assign it in the Menus screen)." => "פס מעל ההדר: מסרים מתחלפים במרכז, ותפריט צד אופציונלי (משייכים במסך התפריטים).",
		"A strip beside the panel" => "רצועת צד בתוך החלונית",
		"A styled photograph with the products marked on it." => "תמונת סצנה מעוצבת עם המוצרים מסומנים עליה.",
		"A sub-category opens" => "תת־קטגוריה נפתחת",
		"A tall banner and a styled scene with the products marked on it." => "באנר גבוה ותמונת סצנה מעוצבת עם המוצרים מסומנים עליה.",
		"A tall photo is cropped to a circle; this picks which part stays. Faces usually sit high, so 35 keeps them whole." => "תמונה גבוהה נחתכת לעיגול; כאן בוחרים איזה חלק נשאר. פנים בדרך כלל גבוה בתמונה, אז 35 שומר עליהן שלמות.",
		"A thin strip at the very top, with a line of news?" => "פס דק בראש העמוד, עם שורת מסרים?",
		"A visitor who reaches the address sees a friendly screen instead of an empty shop. Everyone who can edit the site sees the real thing, and the questionnaire link keeps working. Switch it off on the day the shop opens." => "מבקר שמגיע לכתובת רואה מסך ידידותי במקום חנות ריקה. כל מי שיכול לערוך את האתר רואה את האתר עצמו, וקישור השאלון ממשיך לעבוד. כבו את זה ביום שהחנות נפתחת.",
		"A weekly report, Sunday morning" => "דוח שבועי, ביום ראשון בבוקר",
		"A whole picture keeps its ends and sits on its own ground. Only a cropped picture fills the card, and only a cropped picture can be moved." => "תמונה מלאה שומרת על הקצוות שלה ויושבת על הרקע שלה עצמה. רק תמונה חתוכה ממלאת את הכרטיס, ורק תמונה חתוכה אפשר להזיז.",
		"A wide picture with a heading and a button. The first one on the page is the main banner, and the next screen asks what goes in it; another one is yours to fill in later." => "תמונה רחבה עם כותרת וכפתור. הראשון בעמוד הוא הבאנר הראשי, והמסך הבא שואל מה ייכנס בו; נוסף הוא שלכם למלא בהמשך.",
