		"Addresses that answered 404, how often, and where the visitor came from. Entries older than 30 days clear themselves." => "כתובות שהחזירו 404, כמה פעמים, ומאיפה הגיע המבקר. רשומות בנות יותר מ-30 יום נמחקות מעצמן.",
