		"Admin → Data streams → the stream → Measurement Protocol API secrets. Lets the server report a purchase the browser never did." => "Admin ← Data streams ← הזרם ← Measurement Protocol API secrets. מאפשר לשרת לדווח רכישה שהדפדפן לא דיווח.",
