		"After a conversion, remove the picture it replaced and its old sizes — unless that name is written somewhere on the site, in which case it is always kept." => "אחרי המרה, למחוק את התמונה שהוחלפה ואת הגדלים הישנים שלה — אלא אם השם הזה כתוב במקום כלשהו באתר, ואז הוא תמיד נשמר.",
		"After a conversion, remove the picture it replaced and its old sizes — unless that name is written somewhere on the site, in which case it is always kept. Clearing is what gives up the way back." => "אחרי המרה, להסיר את התמונה שהוחלפה ואת הגדלים הישנים שלה — אלא אם השם הזה כתוב במקום כלשהו באתר, ואז הוא תמיד נשמר. הניקוי הוא מה שמוותר על הדרך חזרה.",
		"After a material change to the policy or the tags, every visitor should choose again. Editing the policy page does this by itself; this button does it without an edit." => "אחרי שינוי מהותי במדיניות או בתגים, כל מבקר צריך לבחור מחדש. עריכת עמוד המדיניות עושה זאת לבד; הכפתור הזה עושה זאת בלי עריכה.",
