		"An accordion — each heading opens under itself" => "אקורדיון — כל כותרת נפתחת מתחתיה",
		"An account with no phone number on file is let through with a warning rather than shut out of the site it runs. Add a mobile number to each staff profile." => "חשבון שאין לו מספר טלפון רשום ייכנס עם אזהרה, ולא ייחסם מהאתר שהוא מנהל. יש להוסיף מספר נייד לפרופיל של כל איש צוות.",
