		"An approved Twilio content template with {{1}} for the product name and {{2}} for the product link." => "תבנית תוכן מאושרת ב-Twilio שכוללת {{1}} עבור שם המוצר ו-{{2}} עבור הקישור למוצר.",
		"An email and a password are both needed." => "צריך גם מייל וגם סיסמא.",
