		"An invite link to the store's group, for the join widget." => "קישור הזמנה לקבוצה של החנות, עבור ווידג׳ט ההצטרפות.",
		"An mp4 file, up to 32MB. It plays without sound and repeats itself, so keep it short. No film ready yet? Put a picture here instead — a film can take its place at any time." => "קובץ mp4, עד 32MB. הוא מתנגן בלי קול וחוזר על עצמו, אז כדאי שיהיה קצר. אין לכם וידאו כרגע? העלו כאן תמונה — תמיד אפשר להחליף אותה בוידאו בהמשך.",
		"An mp4 file. A film plays without sound and repeats itself, so keep it short." => "קובץ mp4. סרטון מתנגן בלי קול וחוזר על עצמו, אז כדאי שיהיה קצר.",
