		"Back in the app's own side menu: App settings, Basic. Fill the privacy policy URL, a category, the app icon and the site domain. For \"User data deletion\" choose \"Data deletion instructions URL\" and point it at the privacy policy page — customers delete themselves under My account, Account details, and the policy should say so." => "חוזרים לתפריט הצד של האפליקציה עצמה: App settings ← Basic. ממלאים כתובת מדיניות פרטיות, קטגוריה, אייקון ודומיין האתר. ב-\"User data deletion\" בוחרים \"Data deletion instructions URL\" ומפנים לעמוד מדיניות הפרטיות — לקוחות מוחקים את עצמם באזור האישי ← פרטי חשבון, וכדאי שהמדיניות תגיד את זה.",
