		"Convert the ticked ones" => "המרת המסומנים",
		"Convert them in the background? It runs on the server for as long as it takes, and you can stop it at any time." => "להמיר אותן ברקע? זה רץ על השרת כמה שצריך, ואפשר לעצור בכל רגע.",
		"Convert these to WebP" => "המר את אלה ל‑WebP",
