		"Created when the address changed." => "נוצר כשהכתובת השתנתה.",
		"Created when the category was deleted." => "נוצר כשהקטגוריה נמחקה.",
		"Created when the content was trashed." => "נוצר כשהתוכן הועבר לפח.",
		"Credit line (empty = © year and site name)" => "שורת קרדיט (ריק = © שנה ושם האתר)",
		"Cross-sells — heading" => "מוצרים נלווים — כותרת",
		"Current consent version: %s" => "גרסת ההסכמה הנוכחית: %s",
		"Custom footer logo" => "לוגו מותאם לפוטר",
		"Custom furniture, engraving, sizes made for the customer. The terms then say there is no cancellation once production began." => "ריהוט בהתאמה, חריטה, מידות שנעשות ללקוח. התקנון יאמר אז שאין ביטול משהחל הייצור.",
		"Custom height" => "גובה מותאם אישית",
		"Custom tab %d" => "טאב מותאם %d",
		"Custom tab %d — content" => "טאב מותאם %d — תוכן",
		"Custom tab %d — title" => "טאב מותאם %d — כותרת",
		"Custom tabs" => "טאבים מותאמים אישית",
		"Customer" => "לקוח",
		"Customer name" => "שם הלקוח",
		"Customer service email" => "מייל שירות לקוחות",
		"Customers" => "לקוחות",
		"Customers can open a chat with you from the site. Leave empty if there is none." => "לקוחות יוכלו לפתוח איתכם שיחה מהאתר. השאירו ריק אם אין.",
		"Customers may hide their address and get an Apple relay — it works, but Apple forwards mail only from registered senders. Under Services (left menu), \"Sign in with Apple for Email Communication\": add the site domain and the shop's sending address, and check they show a green SPF. Skip this and order emails to those customers silently vanish." => "לקוחות עשויים להסתיר את הכתובת ולקבל ממסר של אפל — זה עובד, אבל אפל מעבירה מיילים רק משולחים רשומים. תחת Services (בתפריט השמאלי) ← \"Sign in with Apple for Email Communication\": מוסיפים את דומיין האתר ואת כתובת השליחה של החנות, ובודקים שמופיע SPF ירוק. מדלגים על זה — ואישורי הזמנה ללקוחות האלה נעלמים בשקט.",
		"Customers may pick \"Hide My Email\" and get a relay address — it works, but Apple only forwards mail from registered senders: under Services, \"Sign in with Apple for Email Communication\", add the site domain and the shop's sending address, or order emails will never reach them." => "לקוחות עשויים לבחור \"הסתר את האימייל שלי\" ולקבל כתובת ממסר — היא עובדת, אבל אפל מעבירה מיילים רק משולחים רשומים: תחת Services ← \"Sign in with Apple for Email Communication\" מוסיפים את דומיין האתר ואת כתובת השליחה של החנות, אחרת אישורי הזמנה לא יגיעו אליהם.",
		"Customize → Cart & mini-cart" => "התאמה אישית ← עגלה ומיני-קארט",
		"Customize → Catalogue filters" => "התאמה אישית ← סינון קטלוג",
