		"Customize → Thank-you page" => "התאמה אישית ← דף תודה",
		"Cut to %1\$dpx on desktop and %2\$dpx on phones, as set in Customize → Brand page." => "נחתך ל‑%1\$dpx בדסקטופ ו‑%2\$dpx בנייד, כפי שנקבע בהתאמה אישית ← עמוד מותג.",
