		"Days orders go out" => "ימי משלוח",
		"Days the country is closed are skipped, so no promise lands on one. They are worked out from the calendar and never need updating." => "ימים שבהם המדינה סגורה מדולגים, כך ששום הבטחה לא נופלת עליהם. הם מחושבים מהלוח ולא דורשים עדכון לעולם.",
		"Days the country is closed are skipped, so no promise lands on one. They are worked out from the calendar and never need updating. Next: %s." => "ימים שבהם המדינה סגורה מדולגים, כך ששום הבטחה לא נופלת עליהם. הם מחושבים מהלוח ולא דורשים עדכון לעולם. הקרובים: %s.",
		"Dead clicks" => "לחיצות מתות",
		"Dead clicks are presses on something that does nothing. Read depth is how far down the page half the visitors reached." => "לחיצות מתות הן לחיצות על משהו שאינו עושה דבר. עומק קריאה הוא כמה למטה בעמוד הגיעו מחצית מהגולשים.",
		"Decline button" => "כפתור סירוב",
