		"Deleting is permanent — the files leave the server." => "המחיקה סופית — הקבצים עוזבים את השרת.",
		"Deleting is permanent. Shrinking is not — the original is kept." => "מחיקה היא סופית. הקטנה לא — המקור נשמר.",
		"Deleting the account permanently erases your details from the site. Orders and invoices are kept as the law requires, detached from you." => "מחיקת החשבון מוחקת לצמיתות את הפרטים שלך מהאתר. הזמנות וחשבוניות נשמרות כנדרש בחוק, מנותקות ממך.",
		"Deleting — %1\$d of %2\$d" => "מוחק — %1\$d מתוך %2\$d",
