		"Delivery price" => "מחיר משלוח",
		"Delivery priced by the theme’s shipping rules: a base price, free delivery over a sum, groups priced on their own terms, and regions that cost differently." => "משלוח שמתומחר לפי כללי המשלוח של התבנית: מחיר בסיס, משלוח חינם מעל סכום, קבוצות מוצרים במחיר משלהן ואזורים שעולים אחרת.",
		"Delivery time" => "זמן אספקה",
