		"Delivery, returns, a secure purchase. You fill these in later." => "משלוחים, החזרות, קנייה מאובטחת. ממלאים אותם בהמשך.",
		"Departments and what is inside them — tick the ones worth the front row." => "מחלקות ומה שבתוכן — סמנו את אלה ששוות את השורה הראשונה.",
		"Depth of a plain drop-down" => "עומק תפריט נפתח רגיל",
