		"Design — side, width, title, alignment — lives in the Customizer under \"Login panel\". This screen holds the machinery and the keys." => "העיצוב — צד, רוחב, כותרת, יישור — נמצא בהתאמה אישית תחת \"פאנל התחברות\". המסך הזה מחזיק את המנגנון ואת המפתחות.",
		"Desktop" => "דסקטופ",
