		"Discount" => "הנחה",
		"Discounts" => "הנחות",
		"Display" => "תצוגה",
		"Display a strip of the child categories." => "הצגת רצועה של קטגוריות הבן.",
		"Distinct products" => "מוצרים שונים",
		"Divider line" => "קו מפריד",
		"Do not have one? Pick the ready-made wording above and we write the page for you." => "אין לכם? בחרו למעלה בנוסח המוכן ואנחנו נכתוב את העמוד.",
		"Do not show" => "לא להציג",
		"Do not show the SKU on the product page." => "לא להציג את המק״ט בדף המוצר.",
		"Do not use this category to decide what is similar (%d product in it).\x00Do not use this category to decide what is similar (%d products in it)." => "לא להשתמש בקטגוריה הזו כדי לקבוע מה דומה (מוצר אחד בתוכה).\x00לא להשתמש בקטגוריה הזו כדי לקבוע מה דומה (%d מוצרים בתוכה).",
		"Do you carry goods of makers with a name of their own? Say no and there is nothing more to answer here." => "אתם מחזיקים מוצרים של יצרנים בעלי שם משלהם? אם לא — אין כאן מה למלא.",
		"Do you deliver large items?" => "אתם מספקים פריטים גדולים?",
		"Do you have a shop I can visit?" => "יש לכם חנות שאפשר לבקר בה?",
		"Do you have a store or showroom open to the public?" => "יש לכם חנות או אולם תצוגה פתוחים לקהל?",
		"Do you have a website today?" => "יש לכם אתר היום?",
		"Do you have the details to hand?" => "הפרטים נמצאים אצלכם עכשיו?",
		"Do you sell goods of brands with a name of their own?" => "אתם מוכרים מוצרים של מותגים בעלי שם משלהם?",
		"Do you sell made-to-order products?" => "אתם מוכרים מוצרים בהזמנה אישית?",
		"Documents and the rest" => "מסמכים והשאר",
		"Does a buyer choose something before buying?" => "הקונה בוחר משהו לפני הקנייה?",
		"Does it open the moment something is added?" => "להיפתח ברגע שמוסיפים מוצר?",
		"Does the list start folded on a wide screen?" => "הרשימה מתחילה מקופלת במסך רחב?",
		"Does your product have details worth listing?" => "יש למוצר שלכם פרטים ששווה לפרט?",
		"Don't save" => "ללא",
		"Done and applied" => "הושלם והוחל",
		"Done." => "בוצע.",
		"Done. %s lighter." => "הסתיים. %s פחות.",
		"Done. %s saved." => "הסתיים. נחסכו %s.",
		"Done: %1\$d deleted, %2\$s freed. %3\$d were kept because something still uses them." => "הסתיים: %1\$d נמחקו, %2\$s פונו. %3\$d נשמרו כי משהו עדיין משתמש בהם.",
		"Dot marks" => "נקודות סימון",
		"Double" => "כפול",
		"Down the side" => "בצד",
		"Download" => "הורדה",
		"Download everything as CSV" => "הורדת הכול כ-CSV",
		"Download the record (%d file)\x00Download the record (%d files)" => "הורדת הרישום (קובץ אחד)\x00הורדת הרישום (%d קבצים)",
		"Drag a product to where it should be. Click one, then another, to move several together." => "גררו מוצר למקום שבו הוא צריך להיות. לחיצה על מוצר ואז על עוד אחד מזיזה כמה יחד.",
		"Drag a product to where it should be. Click one, then another, to move several together. Everything you change is kept as you go — there is nothing to save." => "גררו מוצר למקום שבו הוא צריך להיות. לחיצה על מוצר ואז על עוד אחד מזיזה כמה יחד. כל שינוי נשמר תוך כדי — אין מה לשמור.",
		"Drag a product to where it should be. The order is saved as you go, and it holds for this category only — a product can be first here and anywhere else in another. It is used when the shopper has not chosen an order of their own." => "גררו מוצר למקום שבו הוא צריך להיות. הסדר נשמר תוך כדי, והוא תקף לקטגוריה הזאת בלבד — מוצר יכול להיות ראשון כאן ובמקום אחר לגמרי בקטגוריה אחרת. הוא בתוקף כל עוד הגולש לא בחר מיון משלו.",
		"Drag the picture, or use the sliders, to choose what stays in view. Each frame is cut to the banner’s real shape on that screen." => "גררו את התמונה או הזיזו את הסליידרים כדי לבחור מה יישאר בתמונה. כל מסגרת חתוכה בדיוק לצורת הבאנר באותו מסך.",
		"Drag the products on this page into the order you want" => "גררו את המוצרים בעמוד הזה לסדר שאתם רוצים",
		"Drag to reorder is not available here; the order you add them in is the order they appear." => "אין כאן גרירה לסידור; הסדר שבו מוסיפים הוא הסדר שבו הם מוצגים.",
		"Drawer background" => "רקע המגירה",
		"Drawer only" => "במגירה בלבד",
		"Drawer width (px)" => "רוחב המגירה (פיקסלים)",
		"Drawn from" => "נלקחים מ",
		"Dropdown" => "רשימה נפתחת",
		"Dropdowns" => "דרופ-דאונים",
		"E-commerce site by" => "בניית אתר מכירות",
		"Each branch gets its own page, and customers can choose it for collection at the checkout." => "כל סניף מקבל עמוד משלו, ולקוחות יכולים לבחור בו לאיסוף בקופה.",
		"Each button writes a page from a general template built into the theme. The facts on the page (company, address, hours, coordinator, branches) are read live from this screen, so save first, and later edits here show on the page by themselves. Rewriting a page replaces what you edited on it. Before the page is written you confirm that it is a template and not legal advice." => "כל כפתור כותב עמוד מטמפלט כללי המובנה בתבנית. הפרטים בעמוד (חברה, כתובת, שעות, רכז/ת, סניפים) נקראים חי מהמסך הזה — לכן קודם שומרים, ושינוי כאן בהמשך יופיע בעמוד מעצמו. כתיבה מחדש מחליפה מה שערכתם בעמוד. לפני שהעמוד נכתב אתם מאשרים שזהו טמפלט ולא ייעוץ משפטי.",
		"Each button writes a ready-made page from a template built into the theme — no AI, no outside service, nothing leaves the site. The facts on the page (company, address, hours, coordinator, branches) are read live from this screen, so save first, and later edits here show on the page by themselves. Rewriting a page replaces what you edited on it. Read every page once before publishing — a lawyer should confirm anything specific to your business." => "כל כפתור כותב עמוד מוכן מתבנית מובנית בתבנית — בלי AI, בלי שירות חיצוני, שום דבר לא יוצא מהאתר. הפרטים בעמוד (חברה, כתובת, שעות, רכז/ת, סניפים) נקראים חי מהמסך הזה — לכן קודם שומרים, ושינוי כאן בהמשך יופיע בעמוד מעצמו. כתיבה מחדש מחליפה מה שערכתם בעמוד. קראו כל עמוד פעם אחת לפני הפרסום — עורך דין צריך לאשר כל דבר ייחודי לעסק שלכם.",
		"Each category can pick its own layout on its edit screen. Mobile always uses the panel." => "כל קטגוריה יכולה לבחור פריסה משלה במסך העריכה שלה. במובייל תמיד מוצג פאנל.",
		"Each colour and size becomes its own line, tied to the product. This is what lets a shopper land on the one that was advertised." => "כל צבע ומידה הופכים לשורה משלהם, מקושרת למוצר. זה מה שמאפשר לקונה להגיע בדיוק לזו שפורסמה.",
		"Each line becomes a ✓ item." => "כל שורה הופכת לפריט עם ✓.",
		"Each line is one category. Show its children and it becomes a heading with a list under it; hide them and it stays one row of the menu." => "כל שורה היא קטגוריה אחת. הצגת תתי הקטגוריות הופכת אותה לכותרת עם רשימה מתחתיה; הסתרתן משאירה אותה שורה אחת בתפריט.",
		"Each product carries its own add-to-cart button here." => "כאן לכל מוצר יש כפתור הוספה לסל משלו.",
		"Edge to edge" => "מקצה לקצה",
		"Edit" => "עריכה",
		"Edit block" => "עריכת בלוק",
		"Edit brand" => "עריכת מותג",
		"Edit panel" => "עריכת פאנל",
		"Edit the block" => "עריכת הכרטיס",
		"Edit the product" => "עריכת המוצר",
		"Edit your profile" => "עריכת הפרופיל שלך",
		"Eilat" => "אילת",
		"Either the product is missing, or it is called something else in the shop. A synonym fixes the second case in one click." => "או שהמוצר חסר, או שהוא נקרא אחרת בחנות. מילה נרדפת פותרת את המקרה השני בלחיצה.",
		"Elevator" => "מעלית",
		"Email" => "אימייל",
		"Email & SMS" => "מייל וסמס",
		"Email address" => "כתובת אימייל",
		"Email and SMS marketing: remembers you between visits so messages match what you looked at." => "שיווק במייל וב-SMS: זוכר אותך בין ביקורים כדי שההודעות יתאימו למה שראית.",
		"Email and password" => "מייל וסיסמא",
		"Email is not available for this number." => "אין מייל זמין למספר הזה.",
		"Email sign-in" => "כניסה עם מייל",
		"Email sign-in is not available right now." => "כניסה עם מייל אינה זמינה כרגע.",
		"Email us" => "אימייל",
		"Email — never shown" => "אימייל — לא יוצג באתר",
		"Email:" => "דוא\"ל:",
		"Empty = taken automatically from the free-shipping minimum in the shipping zones." => "ריק = נלקח אוטומטית מהמינימום למשלוח חינם שבאזורי המשלוח.",
		"Empty = the WooCommerce sender address." => "ריק = כתובת השולח של ווקומרס.",
		"Empty = the customer service email." => "ריק = מייל שירות הלקוחות.",
		"Empty = the desktop image." => "ריק = תמונת הדסקטופ.",
		"Empty = the store address from WooCommerce → Settings → General." => "ריק = כתובת החנות מהגדרות ווקומרס ← כללי.",
		"Empty = the store phone." => "ריק = הטלפון של החנות.",
		"Empty = the theme's call-to-action colour (Customizer → Design); when that is empty too, the primary colour." => "ריק = צבע ההנעה לפעולה של התבנית (התאמה אישית ← עיצוב); כשגם הוא ריק, הצבע הראשי.",
		"Empty and add" => "רוקן והוסף",
		"Empty follows the default (%s)." => "ריק = ברירת המחדל (%s).",
		"Empty hides it." => "ריק — לא תוצג.",
		"Empty keeps Customize (%s)." => "ריק = כמו בהתאמה אישית (%s).",
		"Empty means: the excerpt, and failing that the content's first 155 characters." => "ריק אומר: התקציר, ואם אין — 155 התווים הראשונים של התוכן.",
		"Empty the log" => "ריקון היומן",
		"Empty-cart text" => "טקסט סל ריק",
		"Enable catalogue filtering" => "הפעלת סינון בקטלוג",
		"Enable filtering" => "הפעלת סינון",
		"End of the menu" => "בסוף התפריט",
		"End side" => "צד הסיום",
		"Enlarges products automatically, so a catalogue of any size looks varied without placing anything by hand. A size chosen on the product itself always wins. 0 = off." => "מגדיל מוצרים אוטומטית, כך שקטלוג בכל גודל נראה מגוון בלי הצבה ידנית. גודל שנבחר על המוצר עצמו תמיד גובר. 0 = כבוי.",
		"Enter phone number" => "מספר טלפון",
		"Enter the IDs below and switch on. Every event the networks expect — product views, categories, searches, add to cart, checkout, payment details, purchases with their value, sign-ups, logins, newsletter — is sent from the browser and, where it matters, from the server too, with one shared id so nothing counts twice." => "מזינים את המזהים למטה ומפעילים. כל אירוע שהרשתות מצפות לו — צפייה במוצר, קטגוריות, חיפושים, הוספה לסל, התחלת קופה, פרטי תשלום, רכישות עם הערך שלהן, הרשמות, כניסות, ניוזלטר — נשלח מהדפדפן, ובמקומות שחשוב גם מהשרת, עם מזהה משותף אחד כך ששום דבר לא נספר פעמיים.",
		"Enter the code" => "הזן את הקוד",
		"Enter the code from the SMS" => "יש להזין את הקוד שהתקבל ב-SMS",
		"Enter your phone — a six-digit code will be sent to verify." => "הזן מספר טלפון — יישלח אליך קוד בן 6 ספרות לאימות.",
		"Entry %s" => "קוד כניסה %s",
		"Entry code" => "קוד כניסה",
		"Entry code (optional)" => "קוד כניסה (אופציונלי)",
		"Entry code is required" => "קוד כניסה — שדה חובה",
		"Equal" => "שווה",
		"Error" => "שגיאה",
		"Eve of %s" => "ערב %s",
		"Event" => "אירוע",
		"Events API access token" => "טוקן גישה ל‑Events API",
		"Events Manager → the pixel → Settings → Conversions API → Generate access token." => "Events Manager ← הפיקסל ← Settings ← Conversions API ← Generate access token.",
		"Events Manager → the pixel → Settings → Events API → Generate access token." => "Events Manager ← הפיקסל ← Settings ← Events API ← Generate access token.",
		"Every" => "כל",
		"Every answer is kept the moment you give it. You can close this and come back whenever you like — the same link brings you back to where you stopped." => "כל תשובה נשמרת ברגע שנתתם אותה. אפשר לסגור ולחזור מתי שרוצים — אותו קישור יחזיר אתכם בדיוק למקום שבו עצרתם.",
		"Every block of other products a product page can carry, and how each one looks." => "כל בלוק של מוצרים אחרים שעמוד מוצר יכול לשאת, ואיך כל אחד נראה.",
		"Every branch is offered unless its own screen says otherwise, where you can also give it the name shoppers see. The branch a shopper picks travels onto the order, shows on the order screen and in the emails, and the orders list can be narrowed to one branch." => "כל סניף מוצע לאיסוף אלא אם נקבע אחרת בעמוד שלו, ושם אפשר גם לקבוע את השם שהלקוח רואה. הסניף שהלקוח בוחר נשמר בהזמנה, מוצג במסך ההזמנה ובמיילים, ואפשר לסנן את רשימת ההזמנות לפי סניף.",
		"Every brand on one page, at /brands/. Brand archives breadcrumb through it." => "כל המותגים בעמוד אחד, בכתובת ‎/brands/‎. פירורי הלחם של עמודי המותגים עוברים דרכו.",
		"Every category page takes this look. A category can choose its own on its edit screen; its pictures always come from the category." => "כל עמודי הקטגוריה מקבלים את המראה הזה. קטגוריה יכולה לבחור מבנה משלה במסך העריכה שלה; התמונות תמיד מגיעות מהקטגוריה עצמה.",
		"Every category the product is in" => "כל הקטגוריות שהמוצר משויך אליהן",
		"Every event is also pushed to the dataLayer as oc_<event>, for any extra tag." => "כל אירוע נדחף גם ל‑dataLayer כ‑‎oc_<event>‎, לכל תג נוסף.",
		"Every four hours" => "כל ארבע שעות",
		"Every frame — catalogue card, gallery at a uniform height, thumbnail rail, search, cart — decides once per picture, on the server. Smart looks at the picture's edges: a product on a plain ground (white, grey, transparent) is shown whole with the frame painted in that same ground, so nothing looks padded; a room or a model fills the frame and is cropped, which a scene survives and a product does not." => "כל מסגרת, כרטיס בקטלוג, גלריה בגובה אחיד, פס תמונות ממוזערות, חיפוש, סל, מחליטה פעם אחת לכל תמונה, בשרת. חכם בוחן את שולי התמונה: מוצר על רקע אחיד (לבן, אפור, שקוף) מוצג במלואו והמסגרת נצבעת באותו רקע, כך ששום דבר לא נראה מרופד; חדר או דוגמנית ממלאים את המסגרת ונחתכים, מה שסצנה סופגת ומוצר לא.",
		"Every hour (recommended)" => "כל שעה (מומלץ)",
		"Every image carries an ALT, unique within its page" => "לכל תמונה יש ALT, ייחודי בתוך העמוד שלה",
		"Every import is remembered as a batch; one click takes the whole batch back out if something went wrong." => "כל ייבוא נשמר כאצווה; לחיצה אחת מוציאה את כל האצווה החוצה אם משהו השתבש.",
		"Every order sends a notice here. Empty = the customer service email." => "כל הזמנה שולחת לכאן הודעה. ריק = מייל שירות הלקוחות.",
		"Every origin" => "כל המקורות",
		"Every page always has a value — freshly imported content included." => "לכל עמוד תמיד יש ערך — כולל תוכן שיובא הרגע.",
		"Every press of the WhatsApp or call button on a product page, by product." => "כל לחיצה על כפתור הוואטסאפ או השיחה בדף מוצר, לפי מוצר.",
		"Every press on something that does something: a link, a button, a picture that leads somewhere." => "כל לחיצה על משהו שעושה משהו: קישור, כפתור, תמונה שמובילה למקום.",
		"Every public form already carries three quiet checks no visitor sees: a trap field robots fill in, a signed timestamp (a form sent under three seconds after it was printed was not filled by a person), and a cap on submissions per hour from one connection. Cloudflare Turnstile adds an invisible challenge on top — no pictures to solve — for the forms you switch it on for." => "בכל טופס ציבורי כבר פועלות שלוש בדיקות שקטות שאף מבקר לא רואה: שדה מלכודת שרובוטים ממלאים, חותמת זמן חתומה (טופס שנשלח פחות משלוש שניות אחרי שהודפס לא מולא על ידי אדם), ותקרה לשליחות בשעה מחיבור אחד. Cloudflare Turnstile מוסיף מעליהן אימות בלתי נראה – בלי תמונות לפתור – לטפסים שתפעילו אותו עבורם.",
		"Every visitor sees a short, honest notice with equal buttons to accept or decline, can change their mind at any time from the footer, and their choice is recorded. The marketing tags, Google Consent Mode and any snippet you park below all follow that choice." => "כל מבקר רואה הודעה קצרה וכנה עם כפתורים שווים לאישור או לסירוב, יכול לשנות את דעתו בכל עת מהפוטר, והבחירה שלו נרשמת. תגי השיווק, Google Consent Mode וכל קטע קוד שתשימו למטה - כולם פועלים לפי הבחירה הזו.",
		"Every visitor will be asked again on their next visit." => "כל מבקר יישאל שוב בביקור הבא שלו.",
		"Everyone" => "כולם",
		"Everyone who signs in" => "כל מי שמתחבר",
		"Everything" => "הכל",
		"Everything in the library is already WebP." => "כל מה שבספרייה כבר WebP.",
		"Everything is saved as you go, so you can stop and come back whenever you like, from your phone or your computer." => "הכל נשמר תוך כדי, כך שאפשר לעצור ולחזור מתי שתרצו, מהטלפון או מהמחשב.",
		"Everything the brand makes" => "כל מה שהמותג מייצר",
		"Everything the site needs in order to speak in your name is already with us: the business, the ways customers reach you, the legal pages and the thank-you page." => "כל מה שהאתר צריך כדי לדבר בשמכם כבר אצלנו: העסק, הדרכים לפנות אליכם, העמודים המשפטיים ודף התודה.",
		"Everything the site needs in order to speak in your name is in. Part two, the last one, is the look of the site: the home page, the catalogue, the product page and the way an order is placed." => "כל מה שהאתר צריך כדי לדבר בשמכם נמצא אצלנו. החלק השני, והאחרון, הוא נראות האתר: דף הבית, הקטלוג, עמוד המוצר והדרך שבה מבצעים הזמנה.",
		"Everything the site needs in order to speak in your name is in. The second part is the look of the site: the home page, the catalogue, the product page and the way an order is placed." => "כל מה שהאתר צריך כדי לדבר בשמכם נמצא אצלנו. החלק השני הוא נראות האתר: דף הבית, הקטלוג, עמוד המוצר והדרך שבה מבצעים הזמנה.",
		"Everything the site needs in order to speak in your name is in. The second part, the look of the site, opens as soon as your site is up, and you will get it in a link of its own. Now we will go over what you filled in and send it." => "כל מה שהאתר צריך כדי לדבר בשמכם נמצא אצלנו. החלק השני, נראות האתר, נפתח ברגע שהאתר שלכם עולה, ותקבלו אותו בקישור נפרד. עכשיו נעבור על מה שמילאתם ונשלח.",
		"Everything you answered is already written into your site — the pages, the home page, the catalogue, the product page, the cart and the checkout." => "כל מה שעניתם כבר כתוב באתר שלכם — העמודים, עמוד הבית, הקטלוג, דף המוצר, הסל והקופה.",
		"Everywhere" => "בכל מקום",
		"Everywhere on the site" => "בכל האתר",
		"Exclude categories" => "החרגת קטגוריות",
		"Exclude product IDs" => "החרגת מזהי מוצרים",
		"Exclude products" => "החרגת מוצרים",
		"Existing — choose below whether to update" => "קיימות — בחרו למטה אם לעדכן",
		"Export CSV" => "ייצוא CSV",
		"Export mapping CSV" => "ייצוא מיפוי CSV",
		"Extra clauses" => "סעיפים נוספים",
		"Facebook and Apple" => "פייסבוק ואפל",
		"Facebook app id" => "מזהה אפליקציית פייסבוק",
		"Facebook sign-in" => "כניסה עם פייסבוק",
		"Fade" => "עמעום",
		"Faded" => "דהוי",
		"Failed" => "נכשלו",
		"Failed orders" => "הזמנות שנכשלו",
		"Fallback" => "ברירת מחדל",
		"Feed settings" => "הגדרות הפיד",
		"Field" => "שדה",
		"Fields" => "שדות",
		"Fields & extras" => "שדות ותוספות",
		"File" => "קובץ",
		"Fill in a phone number or an email address." => "יש למלא מספר טלפון או כתובת אימייל.",
		"Fill in a phone number." => "יש למלא מספר טלפון.",
		"Fill in an email address." => "יש למלא כתובת אימייל.",
		"Fill in the Cardcom details — the terminal number, the API user and its password. The gateway is installed and waiting for them, and switched off until they are in." => "להשלים את פרטי קארדקום — מספר המסוף, משתמש ה‑API והסיסמה שלו. הסולק מותקן ומחכה להם, וכבוי עד שיוזנו.",
		"Fill in the PayPlus details — the API key, the secret key and the payment-page id. The gateway is installed and waiting for them, and switched off until they are in." => "להשלים את פרטי פייפלוס — מפתח ה‑API, המפתח הסודי ומזהה דף התשלום. הסולק מותקן ומחכה להם, וכבוי עד שיוזנו.",
		"Fill the card and crop" => "למלא את הכרטיס ולחתוך",
		"Fill the card, crop" => "למלא את הכרטיס, חיתוך",
		"Fill the four fields above, tick \"Show the Apple button\", Save — and try it. Note: Apple sends the customer's name only on the very first approval; a customer who removes the site under Settings, Apple ID, Sign-In & Security can approve it afresh." => "ממלאים את ארבעת השדות למעלה, מסמנים \"הצג את כפתור אפל\", שומרים — ומנסים. שימו לב: אפל שולחת את שם הלקוח רק באישור הראשון אי-פעם; לקוח שמסיר את האתר תחת הגדרות ← Apple ID ← כניסה ואבטחה יכול לאשר מחדש.",
		"Fill the frame (crop)" => "ממלאת את המסגרת (חיתוך)",
		"Filled" => "מלא",
		"Filled once on the base site and cloned with it. The AI key is deleted from a customer site when the apply finishes; delete it here too when the site is handed over." => "ממולאים פעם אחת באתר ה-base ומשוכפלים איתו. מפתח ה-AI נמחק מאתר הלקוח כשההחלה מסתיימת; מחקו אותו גם כאן כשהאתר נמסר.",
		"Fills the box (crops)" => "ממלאת את התיבה (חותכת)",
		"Fills the frame" => "ממלאה את המסגרת",
		"Films" => "סרטונים",
		"Filter" => "סינון",
		"Filter button opening a panel" => "כפתור סינון שפותח פאנל",
