		"Gather your products — the names, the prices and a picture of each. That is the one thing we cannot do without you." => "לאסוף את המוצרים — השמות, המחירים ותמונה לכל אחד. זה הדבר היחיד שאנחנו לא יכולים לעשות בלעדיכם.",
		"General" => "כללי",
