		"Give it the address of any page on the site and it reads that page the way a browser does: every picture and film the page names, heaviest first. This is the weight a visitor to that page pays." => "הזינו כתובת של כל עמוד באתר, והכלי יקרא אותו כמו שדפדפן קורא: כל תמונה וסרטון שהעמוד מבקש, מהכבד לקל. זה המשקל שמבקר בעמוד הזה משלם.",
		"Give mobile its own" => "מיקום נפרד למובייל",
