		"Held at 1.5s: below that the page is waiting on the server and its own drawing, not on pictures." => "מוחזק על 1.5 שניות: מתחת לזה העמוד מחכה לשרת ולציור של עצמו, לא לתמונות.",
		"Held until I approve" => "חיוב מושהה עד לאישור שלי",
		"Hello, %s" => "שלום, %s",
		"Help line in the header" => "שורת עזרה בהדר",
		"Helpful when the name alone does not say what it is." => "עוזר כשהשם לבדו לא מסביר מה זה.",
		"Helps us understand how the site is used, so we can make it better. The data is aggregated." => "עוזר לנו להבין איך משתמשים באתר, כדי שנוכל לשפר אותו. המידע מצטבר ואינו מזהה.",
		"Here for any question" => "כאן לכל שאלה",
		"Here is everything you told us. Anything missing is marked; tap it to go back." => "הנה כל מה שסיפרתם לנו. מה שחסר מסומן; לחצו עליו כדי לחזור.",
		"Here you decide what your home page offers a visitor. On this side stands everything the page is made of: give a part its heading, move it up or down, throw one away, add another. Beside it the page draws itself as you go. Walk down the list, give every part its heading or its words, and carry on." => "כאן אתם מחליטים מה עמוד הבית יציע לגולש. בצד הזה עומד כל מה שהעמוד עשוי ממנו: אפשר לתת לאזור כותרת, להזיז אותו למעלה או למטה, להסיר אותו או להוסיף עוד אחד. לצידו העמוד מצייר את עצמו תוך כדי. עברו על הרשימה מלמעלה למטה, תנו לכל אזור את הכותרת או התוכן שלו, והמשיכו הלאה.",
		"Hero image — desktop" => "תמונת באנר — דסקטופ",
		"Hero image — mobile (optional)" => "תמונת באנר — מובייל (רשות)",
		"Hi %s," => "שלום %s,",
		"Hi %s, we have good news!" => "היי %s, יש לנו חדשות טובות!",
		"Hi [name], somebody asked to reset the password for your account at [shop].\nIf it was not you, ignore this email — nothing changes until the button below is used.\nThe link is only good for a short while." => "היי [name], מישהו ביקש לאפס את הסיסמה לחשבון שלך ב־[shop].\nאם זה לא אתה, אפשר פשוט להתעלם מהמייל — שום דבר לא משתנה עד שלוחצים על הכפתור שלמטה.\nהקישור תקף לזמן קצר.",
		"Hi [name], your account is ready.\nFrom it you can follow your orders and keep your addresses in one place, so the next checkout is a few taps.\nWelcome — we are glad you are here." => "היי [name], החשבון שלך מוכן.\nממנו אפשר לעקוב אחרי ההזמנות ולשמור את הכתובות במקום אחד, כך שהקנייה הבאה היא עניין של כמה הקשות.\nברוך הבא — טוב שאתה כאן.",
		"Hi," => "שלום,",
