		"How does it decide what is similar?" => "לפי מה היא מחליטה מה דומה?",
		"How far they step under the cursor (px)" => "כמה הם זזים בריחוף (פיקסלים)",
		"How filtering looks. The filter groups themselves stay under Theme settings." => "איך הסינון נראה. קבוצות הסינון עצמן נשארות תחת ״הגדרות תבנית״.",
