		"I have read and understood" => "קראתי והבנתי",
		"I have read and understood: this is a template, not legal advice, and using it is my responsibility." => "קראתי והבנתי: זהו נוסח מוכן, לא ייעוץ משפטי, והשימוש בו באחריותי.",
		"I will choose them myself" => "אבחר בעצמי",
