		"In stock" => "במלאי",
		"In stock first" => "מה שבמלאי קודם",
		"In stock only" => "הצג במלאי בלבד",
		"In stock · arrives 2/12–4/12" => "במלאי · מגיע 2/12–4/12",
		"In the InforU system: Account details → API Token." => "במערכת InforU: פרטי חשבון ← API Token.",
		"In the app dashboard open Use cases, press Customize on the login use case, and under Permissions and features make sure email says \"Ready for testing\". Do not add any other permission — extras like birthday drag the app into a full App Review, and the panel only stores a name and an email anyway." => "בלוח האפליקציה נכנסים ל-Use cases, לוחצים Customize על שימוש ההתחברות, ותחת Permissions and features מוודאים ש-email במצב \"Ready for testing\". לא מוסיפים שום הרשאה אחרת — תוספות כמו יום הולדת גוררות App Review מלא, והפאנל ממילא שומר רק שם ומייל.",
		"In the centre, everything centred" => "במרכז, הכול ממורכז",
