		"No branches yet. Add one and it is offered at the checkout to anyone choosing collection." => "עדיין אין סניפים. הוסיפו סניף והוא יוצע בקופה לכל מי שבוחר איסוף עצמי.",
		"No brands exist yet on this site." => "עדיין אין מותגים באתר.",
		"No brands listed yet — go back and write them, one per line." => "עדיין לא נרשמו מותגים — חזרו אחורה וכתבו אותם, שם בכל שורה.",
		"No brands yet." => "אין עדיין מותגים.",
		"No button — the card leads to the product" => "בלי כפתור — הכרטיס מוביל למוצר",
		"No category by that name." => "אין קטגוריה בשם הזה.",
		"No clearing company yet — PayPlus is installed and waiting, and we send you the link." => "עדיין אין חברת סליקה — פייפלוס מותקן וממתין, ואנחנו שולחים לכם את הקישור.",
		"No clearing company yet — we send the PayPlus link." => "עדיין אין חברת סליקה — נשלח את הקישור לפייפלוס.",
		"No customer email on the invitation, so nothing was sent. Copy the link instead." => "אין מייל לקוח בהזמנה, אז לא נשלח דבר. העתיקו את הקישור במקום.",
		"No darkening" => "ללא",
		"No departments yet. Add the first one and the menu above fills in." => "אין עדיין מחלקות. הוסיפו את הראשונה והתפריט שלמעלה יתמלא.",
		"No discount" => "ללא הנחה",
		"No extra scopes and no Google verification are needed — the sign-in only uses the basic name-and-email profile. Every client site gets its own project and its own keys." => "לא צריך להוסיף Scopes ולא נדרש אימות של גוגל — הכניסה משתמשת רק בפרופיל הבסיסי של שם ומייל. כל אתר לקוח מקבל פרויקט משלו ומפתחות משלו.",
		"No feeds yet." => "אין עדיין פידים.",
		"No file was uploaded, so the page was not written." => "לא הועלה קובץ, ולכן העמוד לא נכתב.",
		"No filter" => "בלי סינון",
		"No filters here" => "ללא סינון בקטגוריה זו",
		"No imports yet." => "אין עדיין ייבואים.",
		"No keys yet — Turnstile stays off until both are saved." => "עדיין אין מפתחות – Turnstile כבוי עד ששניהם יישמרו.",
		"No leads yet." => "אין לידים עדיין.",
		"No link yet" => "עדיין אין קישור",
		"No logo" => "ללא לוגו",
		"No margin around the picture: it meets the card’s edges, and its top corners follow the card." => "בלי שוליים סביב התמונה: היא מגיעה עד קצוות הכרטיס, והפינות העליונות שלה לפי הכרטיס.",
		"No match found" => "לא נמצאה התאמה",
		"No menu is assigned to the primary location yet. Set one on the %s screen and come back." => "עדיין לא שויך תפריט למיקום הראשי. הגדירו אחד במסך %s וחזרו לכאן.",
		"No movement" => "בלי תנועה",
		"No parallax" => "ללא",
		"No picture, no banner." => "בלי תמונה אין באנר.",
		"No post, no field and no page mentions these. Safe to remove." => "אף פריט, שדה או עמוד לא מזכיר אותן. אפשר למחוק בבטחה.",
		"No presses in this period." => "אין לחיצות בתקופה הזו.",
		"No privacy policy page is set. The banner shows without a link until there is one." => "לא הוגדר עמוד מדיניות פרטיות. הבאנר מוצג בלי קישור עד שיהיה כזה.",
		"No problem — nothing here waits for it. At the end of the questionnaire we hand you a link to PayPlus; leave your details there and they come back to you. The shop is built either way, and the card payments switch on the day you have an account." => "אין בעיה — שום דבר כאן לא מחכה לזה. בסוף השאלון נמסור לכם קישור לפייפלוס; תשאירו שם פרטים והם יחזרו אליכם. החנות נבנית כך או כך, והתשלומים בכרטיס נדלקים ביום שיהיה לכם חשבון.",
		"No products match this combination — try removing one of the filters." => "אין מוצרים שתואמים את השילוב — אפשר להסיר אחד מהסינונים.",
		"No progress: %s" => "אין התקדמות: %s",
		"No ratings yet." => "אין דירוגים עדיין.",
		"No ratings yet. Switch the survey on in Thank-you page settings." => "אין דירוגים עדיין. מפעילים את הסקר בהגדרות דף התודה.",
		"No results for \"%s\" — try a different search:" => "לא מצאנו תוצאות עבור ״%s״ — נסו חיפוש אחר:",
		"No rules yet — the form above makes the first one." => "אין עדיין כללים — הטופס למעלה יוצר את הראשון.",
		"No searches recorded in the last 30 days." => "לא נרשמו חיפושים ב־30 הימים האחרונים.",
		"No searches recorded yet." => "עדיין לא נרשמו חיפושים.",
		"No signups yet — they collect from the notify popup on sold-out products." => "אין הרשמות עדיין — הן נאספות מהפופ-אפ במוצרים שאזלו מהמלאי.",
		"No small ones — two in a row, all of them" => "בלי קטנות — שתיים בשורה, כולן",
