		"Past this, sending pauses until midnight and you get an email." => "מעבר לזה השליחה נעצרת עד חצות ואתם מקבלים מייל.",
		"Paste any tag a vendor gave you (a chat widget, a heatmap, another pixel), pick its category, and it will not load until the visitor allows that category. A \"necessary\" tag prints at once. The name appears in the policy's cookie table." => "הדביקו כל תג שספק נתן לכם (צ'אט, מפת חום, פיקסל נוסף), בחרו את הקטגוריה שלו, והוא לא ייטען עד שהמבקר יאשר את הקטגוריה הזו. תג \"הכרחי\" מודפס מיד. השם מופיע בטבלת העוגיות במדיניות.",
		"Paste the address of the page and we take the text from it. Nothing to download and nothing to upload." => "הדביקו את כתובת העמוד ואנחנו ניקח ממנו את התוכן. אין מה להוריד ואין מה להעלות.",
