		"Pick a link on the right, then build what opens underneath it. Order and hierarchy stay on the Menus screen." => "בחרו קישור מימין, ואז בנו את מה שנפתח מתחתיו. הסדר וההיררכיה נשארים במסך התפריטים.",
		"Pick at least one" => "יש לבחור לפחות אחד",
