		"Pick products and an address; the price and the reasons come from the very same calculator the checkout uses — with the rules as saved above." => "בוחרים מוצרים וכתובת; המחיר והסיבות מגיעים מאותו מחשבון בדיוק שהקופה משתמשת בו — לפי הכללים כפי שנשמרו למעלה.",
		"Pick the days, then the hours. Add a line for days with different hours." => "בחרו ימים, ואז שעות. הוסיפו שורה לימים עם שעות שונות.",
