		"Pictures" => "תמונות",
		"Pictures already being served as WebP. Where a conversion left the old file behind, it is offered for removal here." => "תמונות שכבר מוגשות כ‑WebP. איפה שהמרה השאירה מאחור את הקובץ הישן, אפשר למחוק אותו כאן.",
		"Pictures beside the links, in the drawer" => "התמונות שליד הקישורים, במגירה",
		"Pictures in the library" => "תמונות בספרייה",
		"Pictures in the library that are still JPEG or PNG. Converting one rebuilds it and all its sizes as WebP and the site starts serving those. Nothing is deleted unless you ask above, so a conversion can always be undone." => "תמונות בספרייה שעדיין JPEG או PNG. המרה בונה מחדש את התמונה ואת כל הגדלים שלה כ‑WebP, והאתר מתחיל להגיש אותם. שום דבר לא נמחק אלא אם ביקשתם למעלה, כך שתמיד אפשר לחזור אחורה.",
		"Pictures in the library that are still JPEG or PNG. Converting one rebuilds it and all its sizes as WebP and the site starts serving those. Nothing is deleted unless you asked for it in the settings, so a conversion can be undone." => "תמונות בספרייה שעדיין JPEG או PNG. המרה בונה מחדש את התמונה ואת כל הגדלים שלה כ‑WebP, והאתר מתחיל להגיש אותם. שום דבר לא נמחק אלא אם ביקשתם זאת בהגדרות, כך שאפשר לחזור אחורה.",
