		"Placement (mobile)" => "מיקום (מובייל)",
		"Places that cost differently. Match by postcode — an exact code, a range like 88000-88999, or a prefix like 88* — and/or by city name as the customer types it at the checkout (several names, comma-separated). The first matching region wins." => "מקומות שעולים אחרת. זיהוי לפי מיקוד — מדויק, טווח כמו 88000-88999, או קידומת כמו ‎88*‎ — ו/או לפי שם העיר כפי שהלקוח מקליד בקופה (כמה שמות מופרדים בפסיק). האזור הראשון שמתאים קובע.",
