		"Position 1 places the block before the first product. The × at the end of a row removes that placement (save to apply); the block itself stays in the Blocks tab for reuse." => "מיקום 1 מציב את הבלוק לפני המוצר הראשון. ה‑× בסוף שורה מסיר את השיבוץ (שמרו כדי להחיל); הבלוק עצמו נשאר בלשונית ״בלוקים״ לשימוש חוזר.",
