		"Send the request" => "שליחת הבקשה",
		"Send them the PayPlus link so they can open an account. PayPlus is already installed on the site, switched off, waiting for the keys." => "לשלוח להם את הקישור לפייפלוס כדי שיפתחו חשבון. פייפלוס כבר מותקן באתר, כבוי, מחכה למפתחות.",
		"Send this link to a friend: the discount of %1\$s%% waits for them on their first order, and once they buy, a %2\$s%% coupon arrives for you by email." => "אפשר לשלוח את הקישור לחבר: הנחה של %1\$s%% מחכה לו בהזמנה הראשונה, ואחרי שירכוש יגיע אליך במייל קופון של %2\$s%%.",
		"Send us the details for %s and we connect it. It is not one of the two we install ourselves, so that part is by hand." => "שלחו לנו את הפרטים של %s ואנחנו נחבר. זו לא אחת משתי חברות הסליקה שאנחנו מתקינים לבד, אז החלק הזה ידני.",
		"Send what is out of stock to the end?" => "להוריד מוצרים שאזלו לסוף הקטלוג?",
