		"Tablet" => "טאבלט",
		"Tabs" => "טאבים",
		"Tabs for this product only — they join the global tabs. A lower position number appears earlier: description 10, additional information 20." => "טאבים למוצר הזה בלבד — הם מצטרפים לטאבים הכלליים. מספר מיקום נמוך יותר מופיע מוקדם יותר: תיאור 10, מידע נוסף 20.",
		"Tabs on the product page" => "טאבים בדף מוצר",
		"Tabs — the headings in a row, one open underneath" => "טאבים — הכותרות בשורה, אחת פתוחה מתחת",
		"Tag Manager container (optional)" => "קונטיינר Tag Manager (אופציונלי)",
