		"Taken from the current site; read it over once." => "נלקח מהאתר הקיים; כדאי לעבור על זה פעם אחת.",
		"Takes the place of unpaid order #%d, cancelled so that its stock hold would not block this one." => "מחליפה את הזמנה #%d שלא שולמה, שבוטלה כדי ששריון המלאי שלה לא יחסום את ההזמנה הזו.",
		"Taking the money" => "גביית הכסף",
