		"Taxonomies" => "טקסונומיות",
		"Team ID" => "Team ID",
		"Tell us which clearing company you use and send us its details, and we connect it." => "ספרו לנו באיזו חברת סליקה אתם משתמשים ושלחו לנו את הפרטים, ואנחנו נחבר.",
		"Template written; read it once before going live." => "הטמפלט נכתב; לקרוא פעם אחת לפני העלייה לאוויר.",
		"Terminal number" => "מספר מסוף",
		"Terms & conditions" => "תקנון",
		"Terms of sale" => "תקנון",
		"Terms of sale in the site's language: orders and payment, delivery, cancellation and returns per the Consumer Protection Law (14 days, 4 months for eligible customers, 5% or ₪100 fee, the exceptions), warranty, privacy, liability and jurisdiction — written for the kind of store chosen above. Set as the WooCommerce terms page, so the checkout consent and the checkout side panel link to it." => "תקנון בשפת האתר: הזמנה ותשלום, אספקה, ביטול והחזרות לפי חוק הגנת הצרכן (14 יום, 4 חודשים לזכאים, דמי ביטול 5% או 100 ₪, החריגים), אחריות, פרטיות, הגבלת אחריות וסמכות שיפוט — לפי סוג החנות שנבחר למעלה. מוגדר כעמוד התקנון של ווקומרס, כך שאישור התקנון בקופה והפאנל הצדדי בקופה מקשרים אליו.",
		"Terms of sale, privacy policy and accessibility statement. For each one: upload your own file, or use the wording we prepared. Nothing here holds you up — you can send a file later." => "תקנון, מדיניות פרטיות והצהרת נגישות. לכל אחד מהם: להעלות את הקובץ שלכם, או להשתמש בנוסח שהכנו. שום דבר כאן לא מעכב אתכם — אפשר לשלוח קובץ בהמשך.",
		"Terms of sale, privacy policy and accessibility statement. For each one: upload your own file, take it from the site you have today, or use the wording we prepared." => "תקנון, מדיניות פרטיות והצהרת נגישות. לכל אחד מהם: להעלות את הקובץ שלכם, לקחת אותו מהאתר שיש לכם היום, או להשתמש בנוסח שהכנו.",
		"Terms of sale, privacy policy and accessibility statement. For each one: use our template, or upload your own." => "תקנון, מדיניות פרטיות והצהרת נגישות. לכל אחד מהם: להעלות את הקובץ שלכם, או להשתמש בנוסח המוכן שהכנו.",
		"Terms page" => "עמוד התקנון",
		"Test email sent — check the inbox." => "מייל הבדיקה נשלח — בדקו בתיבה.",
		"Test event code (optional)" => "קוד אירוע בדיקה (אופציונלי)",
		"Test message sent — check WhatsApp." => "הודעת הבדיקה נשלחה — בדקו בוואטסאפ.",
		"Test product" => "מוצר בדיקה",
		"Text" => "טקסט",
		"Text & icons colour" => "צבע טקסט ואייקונים",
		"Text alignment" => "יישור הטקסט",
		"Text alternative" => "טקסט חלופי",
		"Text and icons colour — transparent state" => "צבע טקסט ואייקונים — מצב שקוף",
		"Text colour" => "צבע הטקסט",
		"Text colour (empty = the text colour of the site)" => "צבע טקסט (ריק = צבע הטקסט של האתר)",
		"Text lines" => "שורות טקסט",
		"Text links" => "קישורי טקסט",
		"Text meant for search engines usually goes under the products, where it does not push them down." => "טקסט שמיועד למנועי חיפוש בדרך כלל הולך מתחת למוצרים, שם הוא לא דוחף אותם למטה.",
		"Text only, no background" => "טקסט בלבד, ללא רקע",
		"Text position" => "מיקום הטקסט",
		"Text size (px)" => "גודל טקסט (פיקסלים)",
		"Text size in the panel and the drop-down (px)" => "גודל הטקסט בפאנל ובתפריט הנפתח (פיקסלים)",
		"Text size inside (px)" => "גודל הטקסט בפנים (פיקסלים)",
		"Text size inside the panel (px)" => "גודל הטקסט בפאנל (פיקסלים)",
		"Text weight" => "עובי הטקסט",
		"Thank you %s" => "תודה רבה %s",
		"Thank you for your order" => "תודה על ההזמנה",
		"Thank you — you are on the list." => "תודה — נרשמת לרשימה.",
		"Thank you — your order has been received.\nIt is expected to reach you between [from] and [to].\nWe will email you again the moment it leaves us." => "ההזמנה שלך התקבלה, תודה רבה.\nההזמנה צפויה להגיע אליך בין [from] ל‑[to].\nנודיע לך במייל נוסף ברגע שהמשלוח יצא אליך.",
		"Thank you — your order has been received.\nWe are getting it ready, and we will email you the moment it is waiting for you." => "ההזמנה שלך התקבלה, תודה רבה.\nאנחנו מכינים אותה ונעדכן אותך במייל ברגע שהיא תחכה לך.",
		"Thank you!" => "תודה רבה!",
		"Thank you! Everything you answered is already written into your site." => "תודה! כל מה שעניתם כבר כתוב באתר שלכם.",
		"Thank you! Everything you filled in is already on your site. Next we go through the home page, the category page and the product page together — that part opens at the same link, and we let you know when it is ready." => "תודה! כל מה שמילאתם כבר באתר שלכם. בשלב הבא נעבור יחד על עמוד הבית, עמוד הקטגוריה ועמוד המוצר — החלק הזה ייפתח באותו קישור, ונעדכן אתכם כשהוא מוכן.",
		"Thank you! Everything you filled in is already on your site. Our team goes over it and comes back to you with the next step: the products." => "תודה! כל מה שמילאתם כבר באתר שלכם. הצוות שלנו עובר על הכל וחוזר אליכם עם השלב הבא: המוצרים.",
		"Thank you, Dana" => "תודה, דנה",
		"Thank you. We sent you an email — please confirm the request from there." => "תודה. שלחנו לך מייל - יש לאשר את הבקשה משם.",
		"Thank-you page" => "דף תודה",
		"Thank-you page ratings" => "חוות דעת מדף התודה",
		"Thanks for the feedback!" => "תודה על הדירוג!",
		"That address is not on this site." => "הכתובת הזו אינה באתר הזה.",
		"That background reaches" => "הרקע הזה נמשך",
		"That category was not opened, so the button goes to the shop." => "הקטגוריה הזו לא נפתחה, אז הכפתור מוביל לחנות.",
		"That code was not right." => "הקוד שהוזן אינו נכון.",
		"That does not look like a valid phone number." => "זה לא נראה כמו מספר טלפון תקין.",
		"That does not look like an Israeli mobile number." => "זה לא נראה כמו מספר נייד ישראלי.",
		"That does not look like an email address." => "זו לא נראית כמו כתובת מייל תקינה.",
		"That is not the code — look again." => "זה לא הקוד — הציצו שוב.",
		"That order could not be found." => "ההזמנה לא נמצאה.",
		"That page names no pictures or films we can weigh." => "העמוד הזה לא מבקש תמונות או סרטונים שאפשר לשקול.",
		"That print link has expired — pick the orders again." => "קישור ההדפסה פג — בחרו את ההזמנות מחדש.",
		"That product needs a choice made first." => "המוצר הזה דורש בחירה קודם.",
		"That was quick — please take a moment and send again." => "זה היה מהיר – רגע, ואז לשלוח שוב.",
		"That window alone holds %s%% of the last 90 days' orders. A campaign or a message that lands an hour before it works harder." => "החלון הזה לבדו מחזיק %s%% מההזמנות של 90 הימים האחרונים. קמפיין או הודעה שמגיעים שעה לפניו עובדים חזק יותר.",
		"The AI key was deleted from this site." => "מפתח ה-AI נמחק מהאתר הזה.",
		"The About text" => "טקסט האודות",
		"The Cross-sells list on the product's own Linked Products tab. WooCommerce only shows these in the cart; this brings them onto the product page." => "רשימת ה-Cross-sells בלשונית ״מוצרים מקושרים״ של המוצר. ווקומרס מציגה אותם רק בסל; ההגדרה הזו מביאה אותם לעמוד המוצר.",
		"The IDs themselves live in %s." => "המזהים עצמם נמצאים ב%s.",
		"The LCP is optional. Copy it from the speed report and the forecast can say what the saved weight is worth in points." => "ה‑LCP הוא רשות. העתיקו אותו מדוח המהירות והתחזית תוכל לומר כמה שווה המשקל שנחסך בנקודות.",
		"The Team ID sits on the Membership page — copy it into the field above." => "ה-Team ID יושב בעמוד ה-Membership — מעתיקים אותו לשדה למעלה.",
		"The Upsells list on the product's Linked Products tab — a better version of what is being looked at." => "רשימת ה-Upsells בלשונית ״מוצרים מקושרים״ של המוצר — גרסה משודרגת של מה שנצפה כרגע.",
		"The accessibility officer" => "רכז הנגישות",
		"The accessibility statement is written and linked from the footer. Read it once before publishing." => "הצהרת הנגישות נכתבה ומקושרת מהפוטר. קראו אותה פעם אחת לפני הפרסום.",
		"The account and all your personal details will be deleted for good — there is no way back. Orders and invoices are kept as the law requires." => "החשבון וכל הפרטים האישיים שלך יימחקו לתמיד — אין דרך חזרה. הזמנות וחשבוניות נשמרות כנדרש בחוק.",
		"The account did not open — try again." => "החשבון לא נפתח — נסו שוב.",
		"The address" => "הכתובת",
		"The address of the film" => "כתובת הסרטון",
		"The address of the page on your site" => "כתובת העמוד באתר שלכם",
		"The address of your current site" => "הכתובת של האתר הנוכחי שלכם",
		"The air above and below each row." => "האוויר מעל ומתחת לכל שורה.",
		"The aisles of your shop, in the order you want them read. Each one can hold a few of its own. We open the categories and the menu for you; the products come later." => "המחלקות של החנות שלכם, בסדר שבו תרצו שייקראו. בכל אחת אפשר לשים כמה תתי-מחלקות. אנחנו פותחים את הקטגוריות ואת התפריט; המוצרים מגיעים בהמשך.",
		"The alert was removed." => "ההתראה הוסרה.",
		"The answer" => "התשובה",
		"The answers so far" => "התשובות עד כה",
		"The answers were applied again." => "התשובות הוחלו מחדש.",
		"The attribute is already there." => "התכונה כבר קיימת.",
		"The attribute type decides which one leads; the other is the fallback." => "סוג התכונה קובע מה מוצג כברירת מחדל; השני משמש כגיבוי.",
		"The average file" => "הקובץ הממוצע",
		"The band behind the summary and payment column on desktop. Empty = the theme default grey." => "הרקע מאחורי עמודת הסיכום והתשלום בדסקטופ. ריק = האפור של ברירת המחדל.",
		"The banner at the top of every category page that has a banner picture. The picture itself is chosen on each category." => "הבאנר בראש כל עמוד קטגוריה שיש לו תמונת באנר. את התמונה עצמה בוחרים בכל קטגוריה.",
		"The banner at the top of every category page. Each category can still choose its own on its edit screen." => "הבאנר בראש כל עמוד קטגוריה. כל קטגוריה עדיין יכולה לבחור מבנה משלה במסך העריכה שלה.",
		"The banner links to %1\$s. Every site form and the checkout link there too." => "הבאנר מקשר ל%1\$s. כל טופס באתר והתשלום מקשרים לשם גם.",
		"The banner picture" => "תמונת הבאנר",
		"The bar is currently switched off, so these messages are not showing." => "הבר כבוי כרגע, ולכן ההודעות האלה לא מוצגות.",
		"The basics" => "הבסיס",
		"The batch was taken out." => "האצווה הוצאה.",
		"The best sellers" => "הנמכרים ביותר",
		"The best sellers of all" => "הנמכרים ביותר",
		"The better version of the thing being looked at. You pick them per product, in the shop, under Linked products → Upsells. With none picked the row simply does not appear." => "הגרסה הטובה יותר של מה שמסתכלים עליו. בוחרים אותם לכל מוצר, בחנות, תחת מוצרים מקושרים ← Upsells. אם לא בחרתם — השורה פשוט לא מופיעה.",
		"The big picture at the top of the home page. This is where an offer goes, or a launch, or a new collection. Everything you type here appears on the drawing beside you." => "התמונה הגדולה בראש דף הבית. כאן מציעים מבצע, השקה, קולקציה חדשה. כל מה שתקלידו כאן מופיע על הסקיצה שלצידכם.",
		"The big picture at the top of the home page. This is where an offer goes, or a launch, or a new collection. Everything you type here appears on the sketch." => "התמונה הגדולה בראש דף הבית. כאן מציעים מבצע, השקה, קולקציה חדשה. כל מה שתקלידו כאן מופיע בסקיצה.",
		"The big picture at the top of the home page: an offer, a launch, a new collection. First, where the menu stands over it." => "התמונה הגדולה בראש עמוד הבית: מבצע, השקה, קולקציה חדשה. קודם כל, איפה התפריט עומד מעליה.",
		"The big picture at the top. Its contents come on the next screen." => "התמונה הגדולה בראש העמוד. התוכן שלה במסך הבא.",
		"The biggest drop is %s. That is the step to work on first." => "הנשירה הגדולה ביותר היא %s. זה השלב שכדאי לטפל בו קודם.",
		"The block is switched off right now — turn it on under Customize → Product page → Contact." => "הכרטיס כבוי כרגע. מפעילים אותו בהתאמה אישית ← דף מוצר ← יצירת קשר.",
		"The blocks plugin is not active on this site." => "תוסף הבלוקים אינו פעיל באתר הזה.",
		"The branches" => "הסניפים",
		"The branches module is not installed; the branches were not created." => "מודול הסניפים לא מותקן; הסניפים לא נוצרו.",
		"The brand's page, at the top" => "עמוד המותג, בראש העמוד",
		"The brands page" => "עמוד המותגים",
		"The brands we carry" => "המותגים שלנו",
		"The brands you carry" => "המותגים שאתם מוכרים",
		"The built-in tabs. Tab titles and the custom tabs stay under Theme settings." => "הטאבים המובנים. כותרות הטאבים והטאבים המותאמים נשארים תחת ״הגדרות תבנית״.",
		"The business" => "העסק",
		"The business has a store or showroom open to the public" => "לעסק יש חנות או אולם תצוגה הפתוחים לקהל",
		"The button" => "הכפתור",
		"The button opens" => "הכפתור פותח",
		"The button reads \"Add to cart · 1,890\" and follows the quantity and the chosen option." => "על הכפתור ייכתב ״הוספה לסל · 1,890״ והוא עוקב אחרי הכמות ואחרי האפשרות שנבחרה.",
		"The button reads “Add to cart · ₪120” and follows the quantity and the chosen variation." => "הכפתור יציג „הוספה לסל · ₪120” ויתעדכן לפי הכמות והווריאציה שנבחרה.",
		"The buyer gets a coupon to share; the friend gets a discount and the buyer a reward." => "הקונה מקבל קופון לשיתוף; החבר מקבל הנחה והקונה תגמול.",
		"The buying area" => "אזור הקנייה",
		"The card’s own corners follow Global design › Corner rounding." => "הפינות של הכרטיס עצמו נקבעות בעיצוב גלובלי › עיגול פינות.",
		"The cart and the checkout" => "הסל והקופה",
		"The cart is the same icon the header wears." => "הסל הוא אותו אייקון שנבחר להדר.",
		"The cart items' own upsells" => "המוצרים המוצעים שהוגדרו למוצרים שבסל",
		"The cart panel" => "חלונית הסל",
		"The cart total on the checkout button?" => "סכום הסל על כפתור המעבר לקופה?",
		"The catalogue" => "הקטלוג",
		"The catalogue number under the price. A product can also hide its own." => "מספר הקטלוג מתחת למחיר. מוצר יכול גם להסתיר את שלו.",
		"The catalogue's own cards, so the add button follows the card setting." => "כרטיסי הקטלוג הרגילים, כך שכפתור ההוספה נגזר מהגדרת הכרטיס.",
		"The categories" => "קטגוריות",
		"The categories on the home page" => "הקטגוריות בעמוד הבית",
		"The category" => "הקטגוריה",
		"The category page" => "עמוד הקטגוריה",
		"The category shown in its path" => "הקטגוריה שמופיעה בנתיב שלו",
		"The category shown in the product's path" => "הקטגוריה שמופיעה בנתיב של המוצר",
		"The checkout" => "הקופה",
		"The checkout already uses a terms page the theme did not write: %s. It is not touched. Writing ours adds a page next to it, and the checkout stays on the existing one — switch it under WooCommerce → Settings → Advanced only if you decide to." => "לקופה כבר יש עמוד תקנון שלא נכתב על ידי התבנית: %s. הוא לא ייגע. כתיבת העמוד שלנו מוסיפה עמוד לצידו, והקופה נשארת על הקיים — להחליף תחת ווקומרס ← הגדרות ← מתקדם, רק אם תחליטו.",
		"The classic door — email and password, with a forgot-password link" => "הדלת הקלאסית — מייל וסיסמא, עם קישור לשחזור סיסמא",
		"The classic one" => "קלאסית",
		"The clearing company is set up and on. Put a real order through it before the site goes live." => "חברת הסליקה מוגדרת ודלוקה. להעביר דרכה הזמנה אמיתית לפני שהאתר עולה לאוויר.",
		"The code" => "הקוד",
		"The code expired — ask for a new one." => "תוקף הקוד פג — בקשו קוד חדש.",
		"The code is in your inbox." => "הקוד אצלכם במייל.",
		"The codes go out through the service chosen here; only its own fields are asked for below." => "הקודים נשלחים דרך השירות שנבחר כאן; רק השדות שלו יוצגו למטה.",
		"The colours of these products have pictures of their own — a colour gallery or a variation image — and the main photo is none of them. Their catalogue card marks no colour and the product page opens with nothing chosen, so the photo never contradicts the swatch. To have a colour marked again, make the main photo one of that colour's pictures: add it to the colour's gallery (Product data → Colour galleries), set it as that variation's image, or make one of the colour's pictures the main photo." => "לצבעים של המוצרים האלה יש תמונות משלהם – גלריית צבע או תמונת וריאציה – והתמונה הראשית אינה אחת מהן. הכרטיס בקטלוג לא מסמן צבע ודף המוצר נפתח בלי צבע נבחר, כך שהתמונה לעולם לא סותרת את הסוואטש. כדי שיסומן צבע שוב, הפכו את התמונה הראשית לאחת מתמונות אותו צבע: הוסיפו אותה לגלריית הצבע (נתוני מוצר ← גלריות צבע), הגדירו אותה כתמונת הווריאציה, או הפכו אחת מתמונות הצבע לתמונה הראשית.",
		"The columns come from this link's own sub-items, on the screen behind. Add a picture here and they will sit beside it." => "העמודות מגיעות מתתי־הפריטים של הקישור הזה, במסך שמאחור. הוסיפו כאן תמונה והן ישבו לצדה.",
		"The company or business name as registered. Appears on the legal pages only." => "שם החברה או העסק כפי שרשום. מופיע בעמודים המשפטיים בלבד.",
		"The company or business that operates the store, as registered. Empty = the site name." => "החברה או העסק שמפעילים את החנות, כפי שרשום. ריק = שם האתר.",
		"The confirmation and order details were sent by email." => "האישור ופרטי ההזמנה נשלחו במייל.",
		"The connection stumbled — try again." => "החיבור נתקע — נסו שוב.",
		"The contact card is not switched on." => "כרטיס יצירת הקשר במוצר לא מופעל.",
		"The content areas" => "אזורי התוכן",
		"The content width comes from the site's own; on a wide layout it can look the same as the whole page." => "רוחב התוכן נלקח מרוחב התוכן של האתר; בפריסה רחבה הוא עשוי להיראות זהה לכל רוחב העמוד.",
		"The cost is a visitor who opens the page and leaves before the wait is out without touching it — their page view is never sent." => "המחיר הוא מבקר שפותח את העמוד ועוזב לפני שההמתנה נגמרה בלי לגעת בו — צפיית העמוד שלו לא נשלחת כלל.",
		"The cost is a visitor who opens the page and leaves within a couple of seconds without touching it — their page view may never be sent." => "המחיר הוא מבקר שפותח את העמוד ועוזב תוך שניות ספורות בלי לגעת בו — צפיית העמוד שלו עלולה לא להישלח כלל.",
		"The coupon field" => "שדה הקופון",
		"The courier calls whoever opens the door, not whoever paid." => "השליח מתקשר למי שפותח את הדלת, לא למי ששילם.",
		"The cushion with the sofa. You pick them per product, under Linked products → Cross-sells." => "הכרית עם הספה. בוחרים אותם לכל מוצר, תחת מוצרים מקושרים ← Cross-sells.",
		"The customer account was deleted at the customer's request; the order is kept as the law requires." => "חשבון הלקוח נמחק לבקשתו; ההזמנה נשמרת כנדרש בחוק.",
		"The customer did not confirm the template terms." => "הלקוח לא אישר את תנאי הטמפלט.",
		"The customer fills the questionnaire on this site, at a personal link. When they finish, the answers are written into the settings and the pages, and a report lands here and in your mail." => "הלקוח ממלא את השאלון באתר הזה, בקישור אישי. כשהוא מסיים, התשובות נכתבות להגדרות ולעמודים, ודוח מגיע לכאן ולמייל שלכם.",
		"The customer gave points, not a text: the page holds the points and needs writing." => "הלקוח נתן נקודות ולא טקסט: העמוד מכיל את הנקודות וצריך ניסוח.",
		"The customer will send the file later." => "הלקוח ישלח את הקובץ בהמשך.",
		"The customer will send the text later." => "הלקוח ישלח את הטקסט מאוחר יותר.",
		"The daily report goes out in the morning about the whole of yesterday, with the orders themselves; the weekly report goes out on Sunday morning about the week that ended. Both compare to the period before." => "הדוח היומי יוצא בבוקר על כל יום אתמול, כולל ההזמנות עצמן; הדוח השבועי יוצא ביום ראשון בבוקר על השבוע שהסתיים. שניהם מושווים לתקופה שלפניהם.",
		"The delivery address" => "כתובת המשלוח",
		"The details themselves come from Theme settings → Store details. Anything left empty there simply does not appear." => "הפרטים עצמם מגיעים מהגדרות תבנית ← פרטי החנות. מה שריק שם פשוט לא מוצג.",
		"The details you provide will be used to process and deliver your order, for billing and customer service, in line with our %s. Providing them is not required by law, but without them the order cannot be completed." => "הפרטים שמסרת ישמשו לטיפול בהזמנה ולאספקתה, לחיוב ולשירות לקוחות, בהתאם ל%s. מסירת המידע אינה חובה על פי חוק, אך בלעדיה לא ניתן להשלים את ההזמנה.",
		"The drawer" => "המגירה",
		"The drawer — inside a category" => "המגירה — בתוך קטגוריה",
		"The drawer — one level in" => "המגירה — רמה אחת פנימה",
		"The drawer — phone and hamburger" => "המגירה — נייד והמבורגר",
		"The drawer's shape. Titles, free-shipping threshold and upsell rules stay under Theme settings." => "המבנה של המגירה. כותרות, סף המשלוח חינם וכללי ההמלצות נשארים תחת ״הגדרות תבנית״.",
		"The drawers that slide in over the page." => "המגירות שנפתחות מעל העמוד.",
		"The drawing" => "האייקון",
		"The email or the password is wrong." => "המייל או הסיסמא שגויים.",
		"The fields are always shown; this is only whether they may be left empty. Collecting from a branch never requires them." => "השדות תמיד מוצגים; כאן נקבע רק אם מותר להשאיר אותם ריקים. באיסוף מסניף הם אף פעם לא חובה.",
		"The file came up empty." => "הקובץ יצא ריק.",
		"The file could not be uploaded. Allowed: images up to 8MB, or Word / PDF." => "לא הצלחנו להעלות את הקובץ. מותר: תמונות עד 8MB, או Word / PDF.",
		"The file is not on the server." => "הקובץ לא נמצא בשרת.",
		"The file it replaced is gone, so this cannot be undone." => "הקובץ שהוחלף נמחק, ולכן אי אפשר לבטל.",
		"The film" => "הוידאו",
		"The first part is done" => "סיימנו את החלק הראשון",
		"The first part is in: your business details, your content pages and the thank-you page. They are already written into your site." => "החלק הראשון נקלט: פרטי העסק, דפי התוכן ודף התודה. הם כבר כתובים באתר שלכם.",
		"The first scan runs by itself within the hour, in the background." => "הסריקה הראשונה תרוץ לבד תוך שעה, ברקע.",
		"The first step is filling in this questionnaire. It is a series of questions, most of them multiple choice and a few open ones. Everything is saved as you go." => "השלב הראשון בתהליך הוא מילוי טופס השאלון. הטופס בנוי מסדרת שאלות, רוב השאלות הן שאלות אמריקאיות ומעט שאלות פתוחות. הכל נשמר תוך כדי.",
		"The first step is filling in this questionnaire. It is a series of questions, most of them multiple choice and a few open ones. It takes about twenty minutes." => "השלב הראשון בתהליך הוא מילוי טופס השאלון. הטופס בנוי כמסדרת שאלות, רוב השאלות הן אמריקאיות ומעט שאלות פתוחות. זה לוקח בערך עשרים דקות.",
		"The five insights that matter, refreshed every morning" => "חמש התובנות המשמעותיות, מתעדכנות כל בוקר",
		"The floating video loops quietly over the main image; a click opens it full screen." => "הווידאו הצף רץ בלופ שקט מעל התמונה הראשית; לחיצה פותחת אותו על כל המסך.",
		"The foot of the panel" => "תחתית החלונית",
		"The footer has three floors. (1) Content columns: three widget areas — Appearance → Widgets → \"Footer column 1/2/3\"; a text widget, a menu widget, contact details, anything. An empty column simply does not render. (2) The bottom bar: the menu assigned to the \"Footer menu\" location (Appearance → Menus) beside the credit line below. (3) This screen styles it all: background, layout, credit. Order of columns follows the site language direction." => "לפוטר שלוש קומות. (1) עמודות תוכן: שלושה אזורי ווידג'טים — עיצוב ← ווידג'טים ← \"עמודת פוטר 1/2/3\"; ווידג'ט טקסט, תפריט, פרטי קשר — כל דבר. עמודה ריקה פשוט לא מוצגת. (2) הפס התחתון: התפריט שמשויך למיקום \"תפריט פוטר\" (עיצוב ← תפריטים) לצד שורת הקרדיט שלמטה. (3) המסך הזה מעצב את הכל: רקע, פריסה, קרדיט. סדר העמודות עוקב אחרי כיוון שפת האתר.",
		"The friend you shared your code with has placed an order. As promised, a coupon of your own:" => "החבר ששיתפת איתו את הקוד ביצע הזמנה. כמו שהבטחנו — קופון משלך:",
		"The full report" => "הדוח המלא",
		"The gift is for a new customer — it will not apply to your own next order." => "המתנה מיועדת ללקוח חדש — היא לא תחול על ההזמנה הבאה שלך.",
		"The group invite link" => "קישור ההזמנה לקבוצה",
		"The header and the menu" => "ההדר והתפריט",
		"The header itself" => "ההדר עצמו",
		"The heading" => "הכותרת",
		"The heading above it" => "הכותרת מעליו",
		"The heading above them" => "הכותרת מעליהם",
		"The heading links to" => "הכותרת מקשרת אל",
		"The headline on the picture" => "הכותרת על התמונה",
		"The highest one is charged" => "הגבוה מביניהם נגבה",
		"The home page" => "דף הבית",
		"The home page was edited by hand since the last apply; left as it is." => "דף הבית נערך ידנית מאז ההקמה האחרונה; נשאר כפי שהוא.",
		"The index is up to date." => "האינדקס מעודכן.",
		"The invitation was sent." => "ההזמנה נשלחה.",
		"The journal was cleared." => "היומן נוקה.",
		"The key." => "המפתח.",
		"The keys sit at the top of that same Basic screen: App ID is visible, App Secret shows after pressing Show (Facebook asks for your password). Paste both into the fields above." => "המפתחות יושבים בראש אותו מסך Basic: ה-App ID גלוי, וה-App Secret נחשף בלחיצה על Show (פייסבוק תבקש את הסיסמא שלך). מדביקים את שניהם בשדות למעלה.",
		"The last calls the server made to Meta, TikTok and GA4, and what they answered. “Send a test event” fires a PageView through the server with the saved keys." => "הקריאות האחרונות שהשרת עשה למטא, טיקטוק ו‑GA4, ומה הן ענו. ״שליחת אירוע בדיקה״ יורה PageView דרך השרת עם המפתחות השמורים.",
		"The last calls the server made to Meta, TikTok, ChatGPT ads and GA4, and what they answered. “Send a test event” fires a PageView through the server with the saved keys." => "הקריאות האחרונות שהשרת ביצע ל‑Meta, TikTok, פרסום ב‑ChatGPT ו‑GA4, ומה הן ענו. ״שלח אירוע בדיקה״ שולח PageView דרך השרת עם המפתחות השמורים.",
		"The last page before the money. Everything here is already set to what works for most shops — change what is not true of yours." => "העמוד האחרון לפני התשלום. הכל כאן כבר מכוון למה שעובד ברוב החנויות — שנו את מה שלא נכון אצלכם.",
		"The last stretch, where a visitor becomes a customer. Few questions on purpose — everything here is set to what works for most shops." => "הקטע האחרון, שבו מבקר הופך ללקוח. מעט שאלות בכוונה — הכול כאן מכוון למה שעובד לרוב החנויות.",
		"The law asks every business site for an accessibility statement naming a coordinator and stating what the premises offer. The coordinator's channels fall back to the store's own when empty." => "החוק דורש מכל אתר עסקי הצהרת נגישות שמציינת רכז/ת ומה יש בחנות הפיזית. ערוצי הרכז/ת ריקים = ערוצי החנות.",
		"The law asks that withdrawing consent is as easy as giving it." => "החוק דורש שביטול ההסכמה יהיה קל כמו מתן ההסכמה.",
		"The law requires every site to publish the accessibility arrangements of the business. Tick what you have; we write the statement." => "החוק מחייב כל אתר לפרסם את הסדרי הנגישות של העסק. סמנו מה יש אצלכם; אנחנו כותבים את ההצהרה.",
		"The left" => "משמאל",
		"The line or two that sum the product up. Under the heading it is read by everyone; as the first tab it waits for whoever wants it." => "השורה או שתיים שמסכמות את המוצר. מתחת לכותרת כולם קוראים אותן; כלשונית ראשונה הן מחכות למי שרוצה.",
		"The line under it" => "השורה שמתחתיה",
		"The lines that rotate above the header. Leave a slot empty to skip it." => "השורות שמתחלפות מעל ההדר. שדה ריק פשוט מדולג.",
		"The link is cancelled." => "הקישור בוטל.",
		"The link is personal; please do not forward it." => "הקישור אישי; נא לא להעביר אותו הלאה.",
		"The link is ready." => "הקישור מוכן.",
		"The links inside the open panel, not the menu bar above it." => "הקישורים בתוך הפאנל הפתוח, לא שורת התפריט שמעליו.",
		"The links themselves come from the Menus screen. Whether the desktop shows an open menu or a hamburger is the header layout, above." => "הקישורים עצמם מגיעים ממסך התפריטים. האם בדסקטופ מוצג תפריט פתוח או המבורגר — זו פריסת ההדר, למעלה.",
		"The list grows downwards" => "הרשימה נפתחת כלפי מטה",
		"The list of watched pages was last worked out at %s." => "רשימת העמודים במעקב חושבה לאחרונה ב־%s.",
		"The listing a shopper browses: the grid, the card, and everything drawn on it." => "הרשימה שהלקוח גולש בה: הרשת, הכרטיס, וכל מה שמצויר עליו.",
		"The little row of promises near the bottom: a drawing, two or three words, and a line explaining. Four at the most — fewer and stronger reads better." => "שורת ההבטחות הקטנה בתחתית: אייקון, שתיים-שלוש מילים ושורת הסבר. עד ארבע — פחות וחזק יותר נקרא טוב יותר.",
		"The log is empty." => "היומן ריק.",
		"The login SMS budget (%d a day) ran out — sending is paused until midnight. If this is real traffic, raise the cap under Settings, Login." => "תקציב ה-SMS לכניסה (%d ביום) נגמר — השליחה מושהית עד חצות. אם זו תנועה אמיתית, העלו את התקרה בהגדרות ← התחברות.",
		"The logo" => "הלוגו",
		"The logo comes from Site Identity; menus from the Menus screen." => "הלוגו מוגדר בזהות האתר; התפריטים במסך התפריטים.",
		"The logo is the brand’s own image. A brand without one shows its name." => "הלוגו הוא התמונה של המותג עצמו. מותג בלי תמונה יוצג בשמו.",
		"The look of the site" => "נראות האתר",
		"The main banner" => "באנר ראשי בעמוד הבית",
		"The mapping expired — upload again." => "המיפוי פג — העלו שוב.",
		"The media scan is running in the background; the tile updates when it finishes." => "סריקת המדיה רצה ברקע; הקוביה תתעדכן כשהיא תסתיים.",
		"The mega panel — desktop" => "המגה־תפריט — דסקטופ",
		"The menu" => "התפריט",
		"The menu and the banner" => "התפריט והבאנר",
		"The menu bar" => "שורת התפריט",
		"The menu is still empty — go back a screen and name your departments first." => "התפריט עדיין ריק — חזרו מסך אחורה ותנו שמות למחלקות קודם.",
		"The menu of the shop" => "תפריט החנות",
		"The menu sits above the picture" => "התפריט יושב מעל התמונה",
		"The menu sits on the picture" => "התפריט יושב על התמונה",
		"The menu was edited by hand since the last apply; left as it is." => "התפריט נערך ידנית מאז ההחלה האחרונה; נשאר כפי שהוא.",
		"The message did not go out — try again in a moment." => "ההודעה לא יצאה — נסו שוב בעוד רגע.",
		"The method is already there." => "שיטת המשלוח כבר קיימת.",
		"The most it will show. A category with fewer products in it shows what it has." => "המקסימום שיוצג. קטגוריה עם פחות מוצרים תציג את מה שיש בה.",
		"The most useful list on this screen. Every line is a shopper who wanted something and left with an empty panel — and almost every one of them is a missing synonym." => "הרשימה הכי שימושית במסך הזה. כל שורה היא גולש שרצה משהו ויצא עם פאנל ריק — וכמעט כל אחת מהן היא מילה נרדפת חסרה.",
		"The most visited categories" => "הקטגוריות הנצפות ביותר",
		"The most visited products" => "המוצרים הנצפים ביותר",
		"The name" => "השם",
		"The name of the company or business as registered with the tax authority and, for a company, the companies registrar." => "שם החברה או העסק כפי שרשום ברשויות המס, ולחברה — גם ברשם החברות.",
		"The names only. What each product says for them you fill in on the product itself." => "רק השמות. מה שכל מוצר אומר בהם ממלאים על המוצר עצמו.",
		"The new season, in the shop now" => "העונה החדשה, כבר בחנות",
		"The newest" => "החדשים",
		"The number" => "המספר",
		"The number beside each field is what a match there is worth. A word found in the product name outranks the same word found in a description." => "המספר ליד כל שדה הוא כמה שווה התאמה בו. מילה שנמצאה בשם המוצר גוברת על אותה מילה בתיאור.",
		"The number on your user account — the code arrives by SMS." => "המספר שרשום בחשבון המשתמש שלך — הקוד יגיע ב‑SMS.",
		"The number you use in the warehouse. Shoppers rarely need it; a trade customer does." => "המספר שאתם משתמשים בו במחסן. לקוח פרטי כמעט לא צריך אותו, לקוח עסקי כן.",
		"The number your account is registered under." => "המספר המשויך לחשבון שלך",
		"The old name is written somewhere on the site, so the old file was kept." => "השם הישן כתוב במקום כלשהו באתר, ולכן הקובץ הישן נשמר.",
		"The ones I choose" => "אלה שאני בוחר",
		"The ones whose logos stand on the home page." => "אלה שהלוגו שלהם יעמוד בעמוד הבית.",
		"The order beside the form" => "ההזמנה לצד הטופס",
		"The orders" => "ההזמנות",
		"The original could not be copied aside, so nothing was changed." => "לא ניתן היה לשמור עותק של המקור, ולכן שום דבר לא שונה.",
		"The original could not be put back." => "לא ניתן היה להחזיר את המקור.",
		"The original is kept, so this can always be undone." => "המקור נשמר, כך שתמיד אפשר לבטל.",
		"The other side" => "בצד השני",
		"The page" => "העמוד",
		"The page a customer lands on from the menu. Every answer here changes the drawing beside you." => "העמוד שאליו מגיע לקוח מהתפריט. כל תשובה כאן משנה את הסקיצה שלצידכם.",
		"The page a customer lands on from the menu. Every answer here changes the sketch." => "העמוד שאליו מגיע לקוח מהתפריט. כל תשובה כאן משנה את הסקיצה.",
		"The page a customer lands on from the menu: a shelf of products, and whatever stands above it." => "העמוד שאליו הלקוח מגיע מהתפריט: מדף של מוצרים, וכל מה שעומד מעליו.",
		"The page a customer lands on the moment the order goes through. It already shows the order and what happens next; here you choose what else it carries." => "העמוד שהלקוח מגיע אליו ברגע שההזמנה עוברת. הוא כבר מציג את ההזמנה ואת מה שקורה הלאה; כאן בוחרים מה עוד יהיה בו.",
		"The page as a phone shows it — it changes as you answer" => "העמוד כפי שהוא נראה בטלפון — משתנה לפי התשובות",
		"The page could not be read from that address." => "לא הצלחנו לקרוא את העמוד מהכתובת הזו.",
		"The page could not be written." => "לא ניתן היה לכתוב את העמוד.",
		"The page goes back to the arrangement we suggest, and everything you changed here is written over." => "העמוד יחזור לסידור המקורי, וכל השינויים שביצעתם כאן יידרסו.",
		"The page is empty. Add a part, or go back to the arrangement we suggest." => "העמוד ריק. אפשר להוסיף אזור, או לאפס לברירת המחדל.",
		"The page is laid out and waiting for its pictures." => "העמוד סודר וממתין לתמונות.",
		"The page itself, the information tabs, and the other products it shows." => "העמוד עצמו, לשוניות המידע, והמוצרים האחרים שהוא מציג.",
		"The page layout, the contact strip and the order summary are set in %s." => "מבנה העמוד, שורת ערוצי הקשר וסיכום ההזמנה — נקבעים ב%s.",
		"The page of one brand: its products, with its logo, its description and, when it has one, its banner. The pictures are chosen on each brand." => "העמוד של מותג אחד: המוצרים שלו, עם הלוגו, התיאור, וכשיש — הבאנר. התמונות נבחרות בכל מותג.",
		"The page returned nothing." => "העמוד לא החזיר תוכן.",
		"The page was not written: the confirmation box was not ticked." => "העמוד לא נכתב: תיבת האישור לא סומנה.",
		"The page went stale — refresh and try again." => "העמוד התיישן — רעננו ונסו שוב.",
		"The page went stale — refresh it and try again." => "העמוד התיישן – רעננו ונסו שוב.",
		"The page you asked for is not here. Try a search instead." => "העמוד המבוקש לא נמצא. אפשר לנסות חיפוש במקום.",
		"The panel" => "החלונית",
		"The panel a catalogue card opens for a product with options. On a phone it rises from the bottom." => "הפאנל שכרטיס בקטלוג פותח למוצר עם וריאציות. במובייל הוא עולה מלמטה.",
		"The panel shows the last %d days; this screen shows the last 30." => "הפאנל מציג את %d הימים האחרונים; המסך הזה מציג את 30 האחרונים.",
		"The panel that opens" => "הפאנל שנפתח",
		"The panel that slides out when something is added. Beside you it stands open, with whatever you put in it." => "החלונית שנפתחת כשמוסיפים משהו. לידכם היא עומדת פתוחה, עם מה שהכנסתם אליה.",
		"The paragraph under the heading. Each line is its own paragraph. [from] and [to] become the estimated arrival dates — delete that line to leave the estimate out." => "הפסקה שמתחת לכותרת. כל שורה היא פסקה נפרדת. [from] ו‑[to] מוחלפים בתאריכי ההגעה המשוערים — מחיקת השורה הזאת מסתירה את ההערכה.",
		"The paragraph under the heading. Each line is its own paragraph. [shop] and [name] become the shop name and the person's name." => "הפסקה שמתחת לכותרת. כל שורה היא פסקה בפני עצמה. [shop] ו־[name] מוחלפים בשם החנות ובשם הלקוח.",
		"The paragraph under the heading. One line per paragraph." => "הפסקה שמתחת לכותרת. כל שורה היא פסקה.",
		"The person customers can turn to about accessibility. It can be the owner." => "האדם שלקוחות יכולים לפנות אליו בנושא נגישות. יכול להיות בעל העסק.",
		"The photograph" => "התמונה",
		"The picture" => "התמונה",
		"The picture beside the words" => "התמונה שלצד הטקסט",
		"The picture for the banner" => "התמונה לבאנר",
		"The picture's focal point (%)" => "מוקד התמונה (%)",
		"The pictures" => "התמונות",
		"The pictures beside the links" => "התמונות לצד הקישורים",
		"The pieces arrive" => "החלקים נכנסים",
		"The places people press" => "המקומות שלוחצים בהם",
		"The plus again, this time choose Services IDs, Continue. Description: anything; Identifier: the App ID's identifier with a suffix, e.g. com.company.site.web — it must differ from the App ID, the two share one namespace. This identifier is the value for the \"Services ID (client)\" field above. Continue, Register." => "שוב הפלוס, הפעם בוחרים Services IDs ← Continue. Description: מה שרוצים; Identifier: המזהה של ה-App ID עם סיומת, למשל com.company.site.web — הוא חייב להיות שונה מה-App ID, השניים חולקים מרחב שמות אחד. המזהה הזה הוא הערך לשדה \"Services ID (client)\" למעלה. Continue ← Register.",
		"The policy page is written and set as the site's privacy page. Read it once before launch." => "עמוד המדיניות נכתב והוגדר כעמוד הפרטיות של האתר. קראו אותו פעם אחת לפני העלייה לאוויר.",
		"The premises" => "מה יש בעסק",
		"The preview expired — upload again." => "התצוגה המקדימה פגה — העלו שוב.",
		"The price at the top follows the chosen variation" => "המחיר העליון מתחלף לפי הווריאציה שנבחרה",
		"The price on the button itself?" => "המחיר על הכפתור עצמו?",
		"The privacy policy needs your approval." => "צריך לאשר את מדיניות הפרטיות.",
		"The privacy policy page has its own button under %s." => "לעמוד מדיניות הפרטיות יש כפתור משלו תחת %s.",
		"The product card" => "כרטיס המוצר",
		"The product page" => "עמוד המוצר",
		"The product page opens with no colour or size selected, and catalogue cards mark no colour. Unticked, a product without default form values opens on the colour of its main photo." => "דף המוצר נפתח בלי צבע או מידה מסומנים, והכרטיס בקטלוג לא מסמן צבע. בלי הסימון, מוצר שלא הוגדרו לו ערכי ברירת מחדל נפתח על הצבע של התמונה הראשית.",
		"The product you asked to follow is available again. Quantities may be limited — first come, first served." => "המוצר שביקשתם לעקוב אחריו זמין שוב. הכמויות עשויות להיות מוגבלות — כל הקודם זוכה.",
		"The products" => "המוצרים",
		"The products, in the order you want them" => "המוצרים, בסדר שתרצו",
		"The provisioning secret is set in wp-config.php." => "סוד ההקמה מוגדר ב-wp-config.php.",
		"The question" => "השאלה",
		"The questionnaire is waiting for you. It takes about fifteen minutes, and everything is saved as you go." => "השאלון מחכה לכם. הוא לוקח כרבע שעה, והכל נשמר תוך כדי.",
		"The regular variables work here, plus %%filename%% and %%index%%." => "המשתנים הרגילים עובדים כאן, בתוספת %%filename%% ו-%%index%%.",
		"The right" => "מימין",
		"The rule also fires while the word is still being typed, so a shopper sees the pin from the third letter on." => "הכלל פועל גם בזמן שהמילה עדיין מוקלדת, כך שהגולש רואה את הקידום כבר מהאות השלישית.",
		"The rule for every brand; a brand can choose for itself on its own screen. Long text folds to two lines with \"Read more\" either way." => "הכלל לכל המותגים; מותג יכול לבחור לעצמו במסך שלו. טקסט ארוך מתקפל לשתי שורות עם \"קרא עוד\" בכל מקרה.",
		"The rule for every category; a category can choose for itself on its own screen. Brand pages have their own rule under Brand page." => "הכלל לכל הקטגוריות; קטגוריה יכולה לבחור לעצמה במסך שלה. לעמודי מותג יש כלל משלהם תחת עמוד מותג.",
		"The same product in other colours. Links sync both ways: connect black and grey here and each of them links back automatically." => "אותו מוצר בצבעים אחרים. הקישור מסתנכרן לשני הכיוונים: קשרו כאן שחור ואפור — וכל אחד מהם יקושר חזרה אוטומטית.",
		"The same words on every product — care instructions, a size guide, a warranty." => "אותו טקסט בכל מוצר — הוראות טיפול, טבלת מידות, אחריות.",
		"The same, for an order being collected rather than delivered." => "אותו הדבר, להזמנה שנאספת במקום נשלחת.",
		"The same, for an order being collected. Left empty, the delivery wording is used." => "אותו הדבר להזמנה שנאספת. אם ריק, יוצג הנוסח של המשלוח.",
		"The scan expired. Please run it again." => "הסריקה פגה. יש להריץ אותה שוב.",
		"The screen" => "המסך",
		"The second picture" => "התמונה השנייה",
		"The service is provided online only; the business has no store open to the public." => "השירות ניתן באופן מקוון בלבד; לעסק אין חנות הפתוחה לקהל.",
		"The service line" => "שורת השירות",
		"The shelf of products" => "מדף המוצרים",
		"The shop picks these itself — you choose nothing per product. A shopper who did not find it here finds the neighbour." => "החנות בוחרת אותם לבד — אתם לא בוחרים כלום לכל מוצר. מי שלא מצא כאן, מוצא את השכן.",
		"The shopper's own hold" => "השריון של הלקוח עצמו",
		"The short description" => "התיאור הקצר",
		"The short promises that sit under the buy button. Three to begin with, up to four — write what is true of your shop." => "ההבטחות הקצרות שעומדות מתחת לכפתור הקנייה. שלוש להתחלה, עד ארבע — כתבו מה שנכון לחנות שלכם.",
		"The short promises that sit under the buy button. Up to four; leave them empty and none show." => "ההבטחות הקצרות שיושבות מתחת לכפתור הקנייה. עד ארבע; אם נשאיר ריק — לא תוצג אף אחת.",
		"The short version of what your terms say." => "הגרסה הקצרה של מה שכתוב בתקנון שלכם.",
		"The side the page starts from" => "בצד שממנו מתחיל העמוד",
		"The site address you want (domain)" => "כתובת האתר הרצויה (דומיין)",
		"The site is being built" => "האתר בהקמה",
		"The site width, like the content" => "לרוחב האתר, כמו התוכן",
		"The site you have today" => "האתר שיש לכם היום",
		"The sketch" => "סקיצה",
		"The sketch (desktop)" => "סקיצה (דסקטופ)",
		"The sketch (phone)" => "סקיצה (מובייל)",
		"The statement lists the branches (%d now) in a table, one row per branch. Tick what each branch offers on its own screen, under Branches → Accessibility." => "ההצהרה מציגה את הסניפים (%d כרגע) בטבלה, שורה לכל סניף. מה יש בכל סניף מסמנים במסך שלו, תחת סניפים ← נגישות.",
		"The statement regulation 35 requires: the standard the site follows, the adaptations the theme really provides, how to enlarge text and raise contrast from the browser, the premises table, the coordinator and how to report a problem. Linked from the footer next to the privacy link." => "ההצהרה שתקנה 35 דורשת: התקן שהאתר עומד בו, ההתאמות שהתבנית באמת מספקת, איך להגדיל טקסט ולהגביר ניגודיות מהדפדפן, טבלת החנות הפיזית, הרכז/ת ואיך מדווחים על בעיה. מקושרת מהפוטר ליד קישור הפרטיות.",
		"The stock line takes turns between what the stock is doing and when the parcel would arrive. Counting starts tomorrow and skips the days you do not send." => "שורת המלאי מתחלפת בין מצב המלאי לבין מועד ההגעה המשוער. הספירה מתחילה ממחר ומדלגת על הימים שבהם אינכם שולחים.",
		"The store described once. Every page that shows these details reads from here — the checkout help line, the thank-you page, the emails, the generated terms and accessibility pages, and any text where you write {phone}, {email}, {whatsapp}, {company}, {address} or {hours}. An empty field simply does not appear." => "החנות מתוארת פעם אחת. כל עמוד שמציג את הפרטים קורא מכאן — שורת העזרה בקופה, עמוד התודה, המיילים, עמודי התקנון והנגישות שנכתבים מכאן, וכל טקסט שבו כותבים {phone}, {email}, {whatsapp}, {company}, {address} או {hours}. שדה ריק פשוט לא מופיע.",
		"The store's own channels, entered once. Every page that shows them reads from here — the checkout help line, the thank-you page, and any text where you write {phone}, {email} or {whatsapp}. An empty field simply does not appear." => "ערוצי הקשר של החנות, במקום אחד. כל עמוד שמציג אותם מושך מכאן — שורת העזרה בקופה, דף התודה, וכל טקסט שכתוב בו ‎{phone}‎, ‎{email}‎ או ‎{whatsapp}‎. שדה ריק פשוט לא מוצג.",
		"The store, the team, the workshop. Optional." => "החנות, הצוות, הסדנה. לא חובה.",
		"The street and the house number are always required. Tick whatever a courier of yours cannot do without." => "הרחוב ומספר הבית תמיד חובה. סמנו את מה שהשליחים שלכם לא יכולים בלעדיו.",
		"The strip above the header" => "הפס שמעל ההדר",
		"The strip above the header, the header itself, and the menu that drops out of it." => "הרצועה שמעל ההדר, ההדר עצמו, והתפריט שנפתח ממנו.",
		"The strip every page of the shop wears. Whatever you write here, the sketch beside you puts in its place." => "הפס שכל עמוד בחנות לובש. כל מה שתכתבו כאן, הסקיצה שלצידכם שמה במקומו.",
		"The sum on the order button?" => "הסכום על כפתור ביצוע ההזמנה?",
		"The tab is already there." => "הלשונית כבר קיימת.",
		"The terms page is written and set as the checkout terms page. Read it once before publishing." => "עמוד התקנון נכתב והוגדר כעמוד התקנון של הקופה. קראו אותו פעם אחת לפני הפרסום.",
		"The terms page is written. The checkout keeps the terms page it already had, which the theme did not write — switch it under WooCommerce → Settings → Advanced only if you decide to." => "עמוד התקנון נכתב. הקופה נשארת עם עמוד התקנון שכבר היה לה, שלא נכתב על ידי התבנית — להחליף תחת ווקומרס ← הגדרות ← מתקדם, רק אם תחליטו.",
		"The test email could not be sent." => "לא ניתן היה לשלוח את מייל הבדיקה.",
		"The test report was sent." => "דוח הבדיקה נשלח.",
		"The thank-you page" => "דף התודה",
		"The theme prices delivery" => "התבנית מתמחרת את המשלוח",
		"The top of the page" => "ראש העמוד",
		"The waiting list" => "רשימת הממתינים",
		"The weight is measured. The seconds and the points are a forecast for one metric on a simulated phone — treat them as the direction, not the number." => "המשקל נמדד. השניות והנקודות הן תחזית למדד אחד בטלפון מדומה — יש להתייחס אליהן ככיוון, לא כמספר.",
		"The whole category" => "כל הקטגוריה",
		"The whole page" => "כל רוחב העמוד",
		"The whole picture" => "התמונה במלואה",
		"The whole screen, edge to edge" => "לכל רוחב המסך, מקצה לקצה",
		"The whole shop" => "כל החנות",
		"The widest, best one you have — 1920 pixels across or more. It can be changed later." => "הרחבה והטובה ביותר שיש לכם, ברוחב 1920 פיקסלים ומעלה. אפשר להחליף בהמשך.",
		"The widest, best picture you have — 1920 pixels across or more. Without it the home page opens with no banner, and you can always add it later." => "התמונה הרחבה והטובה ביותר שיש לכם, ברוחב 1920 פיקסלים ומעלה. בלעדיה דף הבית ייפתח בלי באנר, ותמיד אפשר להוסיף אותה בהמשך.",
		"The width of the content" => "רוחב התוכן",
		"The word Sale" => "המילה מבצע",
		"The word lifts" => "המילה מתרוממת",
		"The wording on the invitation" => "הניסוח על ההזמנה",
		"The words" => "הטקסט",
		"The words are" => "הטקסט",
		"The words beside the dot (empty = \"Online now\")" => "הטקסט ליד הנקודה (ריק = ״זמינים עכשיו״)",
		"The words sit" => "מיקום הטקסט",
		"The words that run across" => "הטקסט שרץ",
		"Their corners" => "הפינות שלהן",
		"Their logo" => "הלוגו שלהם",
		"Their name" => "השם שלהם",
		"Their own list is in the mail they received, so you both know what is waiting on whom." => "הרשימה שלהם נמצאת במייל שהם קיבלו, כך ששניכם יודעים על מי מחכה מה.",
		"Theme colour" => "צבע התבנית",
		"Theme settings" => "הגדרות תבנית",
		"Then we go over the site with you before it goes live." => "ואז עוברים איתכם על האתר לפני שהוא עולה לאוויר.",
		"There are unsaved changes. Close anyway?" => "יש שינויים שלא נשמרו. לסגור בכל זאת?",
		"There is already an accessibility page the theme did not write: %s. It is not touched. If it is complete, link it from the footer menu and skip this button; writing ours adds a second page and the footer link points at ours." => "כבר קיים עמוד נגישות שלא נכתב על ידי התבנית: %s. הוא לא ייגע. אם הוא שלם — קשרו אותו מתפריט הפוטר ודלגו על הכפתור; כתיבת העמוד שלנו מוסיפה עמוד שני והקישור בפוטר יצביע על שלנו.",
		"There is no original kept for this one." => "לא נשמר מקור לקובץ הזה.",
		"There is nothing left over for this one." => "לא נשארו קבצים ישנים לתמונה הזו.",
		"There is nothing to go back to for this one." => "אין למה לחזור עבור התמונה הזו.",
		"These details appear on the site, in the emails customers receive and on the legal pages. Everything can be changed later." => "הפרטים האלה מופיעים באתר, במיילים שהלקוחות מקבלים ובעמודים המשפטיים. הכל ניתן לשינוי אחר כך.",
		"These products have colour galleries, but their main photo sits in none of them. Their catalogue card marks no colour and the product page opens with nothing chosen, so the photo never contradicts the swatch. To have a colour marked again, add the main photo to that colour's gallery (Product data → Colour galleries), or make one of the gallery pictures the main photo." => "למוצרים האלה יש גלריות צבע, אבל התמונה הראשית שלהם לא נמצאת באף אחת מהן. הכרטיס בקטלוג לא מסמן צבע ודף המוצר נפתח בלי צבע נבחר, כך שהתמונה לעולם לא סותרת את הסוואטש. כדי שיסומן צבע שוב, הוסיפו את התמונה הראשית לגלריה של אותו צבע (נתוני מוצר ← גלריות צבע), או הפכו אחת מתמונות הגלריה לתמונה הראשית.",
		"These results, from that brand" => "התוצאות האלה, מהמותג הזה",
		"These results, in that category" => "התוצאות האלה, בקטגוריה הזו",
		"They add up" => "הם מצטברים",
		"They appear under the products, never mixed into them." => "הם מוצגים מתחת למוצרים, אף פעם לא מעורבבים בהם.",
		"They left the clearing details for later. Chase them, put them in, and switch the gateway on." => "הם השאירו את פרטי הסליקה להמשך. לרדוף אחריהם, להזין, ולהדליק את הסולק.",
		"They open one at a time wherever they stand." => "הם נפתחים אחד בכל פעם, בכל מקום שבו יעמדו.",
		"They see page numbers and press one" => "רואים מספרי עמודים ולוחצים",
		"They stand at the foot of the page, and the shop picks them itself — by what they share with this one: the category, the name, the price, the tags." => "הם עומדים בתחתית העמוד, והחנות בוחרת אותם לבד — לפי מה שמשותף להם ולמוצר הזה: הקטגוריה, השם, המחיר, התגיות.",
		"They use a clearing company we do not install ourselves — get its details and connect it by hand. Both of our gateway plugins were taken off the site." => "הם משתמשים בחברת סליקה שאנחנו לא מתקינים לבד — להשיג את הפרטים ולחבר ידנית. שני תוספי הסליקה שלנו הוסרו מהאתר.",
		"Thickness of the line (px)" => "עובי הקו (פיקסלים)",
		"Thin" => "דק",
		"Thin line" => "קו עדין",
		"This category has an order of its own." => "לקטגוריה הזאת יש סדר משלה.",
		"This category has no order of its own yet — drag a product and it will have one." => "לקטגוריה הזאת עדיין אין סדר משלה — גררו מוצר אחד ויהיה לה.",
		"This coupon cannot be applied." => "לא ניתן להחיל את הקופון הזה.",
		"This email is already registered — try signing in with Google, or use another address." => "המייל כבר רשום — נסו להיכנס עם גוגל, או השתמשו בכתובת אחרת.",
		"This gift is meant for a friend — it cannot be used on your own order." => "המתנה הזו מיועדת לחבר — לא ניתן להשתמש בה בהזמנה שלך.",
		"This is not an address yet — pick one from the list, or paste a link." => "זו עדיין לא כתובת — בחרו מהרשימה, או הדביקו קישור.",
		"This is where free delivery, payments without interest or an opening offer goes." => "כאן נכנסים משלוח חינם, תשלומים ללא ריבית או מבצע פתיחה.",
		"This is your choice" => "זו הבחירה שלכם",
		"This item's category" => "הקטגוריה של הפריט",
		"This link is no longer active" => "הקישור הזה כבר לא פעיל",
		"This link is no longer active. Open the newest link we sent you, and nothing you filled in will be lost." => "הקישור הזה כבר לא פעיל. פתחו את הקישור העדכני ששלחנו לכם, ושום דבר שמילאתם לא ילך לאיבוד.",
		"This month" => "החודש",
		"This number is already registered — sign in with it instead." => "המספר כבר רשום — פשוט היכנסו איתו.",
		"This page is a general template drafted with the help of artificial intelligence by the theme's makers. It is a starting point for inspiration only — not legal advice, and not tailored to your business. Before publishing, have the text reviewed by a lawyer and adapted to your business, and read every line yourself. Using the page is the sole responsibility of the site owner; the theme's makers bear no responsibility for its content or for any claim that may arise from it." => "העמוד הזה הוא נוסח כללי שנוסח בעזרת בינה מלאכותית על ידי יוצרי התבנית. הוא נקודת פתיחה להתרשמות בלבד — לא ייעוץ משפטי, ולא מותאם לעסק שלכם. לפני פרסום כדאי להעביר את הנוסח לעורך דין, להתאים אותו לעסק ולקרוא כל שורה. השימוש בעמוד הוא באחריות בעל האתר בלבד; יוצרי התבנית אינם אחראים לתוכנו או לכל תביעה שתנבע ממנו.",
		"This page is a general template drafted with the help of artificial intelligence by the theme's makers. It is a starting point for inspiration only — not legal advice, and not tailored to your business. Before publishing, have the text reviewed by a lawyer and adapted to your business, and read every line yourself. Using the page is the sole responsibility of the site owner; the theme's makers bear no responsibility for its content or for any claim that may arise from it. Clicking \"Create the page\" confirms that you have read and understood this." => "עמוד זה הוא נוסח כללי מוכן שנכתב בעזרת בינה מלאכותית על ידי יוצרי התבנית. הוא נקודת פתיחה והשראה בלבד — לא ייעוץ משפטי, ולא מותאם לעסק שלכם. לפני הפרסום יש להעביר את הטקסט לעיון עורך/ת דין ולהתאימו לעסק, ולקרוא כל שורה בעצמכם. השימוש בעמוד הוא באחריות בעל האתר בלבד; יוצרי התבנית אינם נושאים באחריות לתוכנו או לכל טענה שתנבע ממנו. לחיצה על \"צור את העמוד\" מאשרת שקראתם והבנתם זאת.",
		"This page loads %1\$d files, %2\$s of pictures and film." => "העמוד טוען %1\$d קבצים, %2\$s של תמונות וסרטונים.",
		"This panel is full." => "הפאנל מלא.",
		"This part is not on the page" => "האזור הזה לא נמצא בעמוד",
		"This period" => "התקופה הנוכחית",
		"This product" => "המוצר הזה",
		"This product and whatever you tie to it, as one add to the cart, with a discount if you want one. It only shows on a product you have built a bundle for." => "המוצר הזה ומה שתקשרו אליו, כהוספה אחת לסל, עם הנחה אם תרצו. מופיע רק על מוצר שבניתם לו חבילה.",
		"This product has not sold yet." => "המוצר עדיין לא נמכר.",
		"This server cannot write WebP, so nothing here will work. Ask the host to enable it." => "השרת הזה לא יודע לכתוב WebP, ולכן שום דבר כאן לא יעבוד. בקשו מהאחסון להפעיל את זה.",
		"This server cannot write WebP, so there is nothing to forecast." => "השרת הזה אינו יודע לכתוב WebP, ולכן אין מה לחזות.",
		"This server cannot write WebP." => "השרת הזה לא יודע לכתוב WebP.",
		"This shop has branches" => "לחנות הזאת יש סניפים",
		"This site has nowhere to keep brands yet." => "לאתר הזה אין עדיין איפה לשמור מותגים.",
		"This store has branches" => "לחנות הזאת יש סניפים",
		"Those could not be added." => "לא ניתן היה להוסיף אותם.",
		"Those details were not right." => "הפרטים שהוזנו אינם נכונים.",
		"Those links under the cursor" => "אותם קישורים בריחוף",
		"Thousands of pictures is hours of work. Start it here and it carries on by itself — close the tab, come back whenever. Whatever is converted before you stop stays converted." => "אלפי תמונות הן שעות עבודה. התחילו כאן והמרה תימשך מעצמה — אפשר לסגור את הלשונית ולחזור מתי שרוצים. כל מה שהומר עד שתעצרו נשאר מומר.",
		"Three" => "שלושה",
		"Three quick presses on the same spot. Someone pressed, nothing happened, and they pressed again and again: a control that does not answer, or something that only looks like one." => "שלוש לחיצות מהירות באותו מקום. מישהו לחץ, שום דבר לא קרה, והוא לחץ שוב ושוב: כפתור שלא מגיב, או משהו שרק נראה כמו כפתור.",
		"Three ways to lay out the same shop. Look through them and take the one you like — nothing here is final, and every part of it can be moved later." => "שלוש דרכים לסדר את אותה חנות. עברו ביניהן וקחו את זו שמוצאת חן בעיניכם — שום דבר כאן אינו סופי, וכל חלק ניתן להזזה בהמשך.",
		"Three ways to lay out the same shop. Pick the one that looks like you — nothing here is final, and every part of it can be moved later." => "שלוש דרכים לסדר את אותה חנות. בחרו את זו שנראית לכם — שום דבר כאן אינו סופי, וכל חלק ניתן להזזה בהמשך.",
		"Three — a grandchild as well" => "שלוש — כולל רמה שלישית",
		"Threshold override" => "דריסת סף ידנית",
		"Thumbnail size" => "גודל תמונות ממוזערות",
		"Thumbnails beside" => "ממוזערות בצד",
		"Thumbnails under" => "ממוזערות מתחת",
		"Thursday" => "חמישי",
		"Tick everything you have. Nothing ticked is fine too; the statement says so honestly." => "סמנו כל מה שיש. גם בלי סימון זה בסדר; ההצהרה תגיד את זה בכנות.",
		"Tick per branch. Each one shows its own row in the statement." => "סמנו לכל סניף בנפרד. לכל אחד תהיה שורה משלו בהצהרה.",
		"Tick the ones worth the front row. Nothing ticked and we show them all." => "סמנו את אלה ששוות את השורה הראשונה. בלי סימון — נציג את כולן.",
		"Tight" => "צפוף",
		"TikTok" => "טיקטוק",
		"TikTok catalogue" => "קטלוג טיקטוק",
		"Tile size" => "גודל האריח",
		"Times" => "פעמים",
		"Timing" => "תזמון",
		"Title" => "כותרת",
		"Title alignment" => "יישור כותרת",
		"Title override" => "כותרת מותאמת",
		"Title size — desktop (px, 0 = theme default)" => "גודל הכותרת - דסקטופ (px, 0 = ברירת המחדל של התבנית)",
		"Title size — mobile (px, 0 = same as desktop)" => "גודל הכותרת - מובייל (px, 0 = כמו בדסקטופ)",
		"Title template" => "תבנית כותרת",
		"Title text — [product] becomes the product name" => "טקסט הכותרת. [product] הופך לשם המוצר",
		"Title — maximum lines" => "כותרת — מקסימום שורות",
		"Title — the phone step" => "כותרת — שלב הטלפון",
		"To" => "עד מחיר",
		"To address" => "לכתובת",
		"To another page — I will give the address" => "לעמוד אחר — אני אתן את הכתובת",
		"To approve" => "לאישור",
		"To cart" => "לסל",
		"To convert" => "להמרה",
		"To one of the departments" => "לאחת המחלקות",
		"To push a single product up in every search, or to keep it out of search entirely, use the Search tab on the product itself." => "כדי לדחוף מוצר בודד למעלה בכל חיפוש, או להוציא אותו לגמרי מהחיפוש, השתמשו בלשונית ״חיפוש״ במוצר עצמו.",
		"To the product" => "למוצר",
		"To the product page" => "לדף המוצר",
		"To the shop" => "לחנות",
		"To the shop, all the products" => "לחנות, כל המוצרים",
		"To the side" => "מיושר לצד",
		"Today" => "היום",
		"Too many at once." => "יותר מדי בבת אחת.",
		"Too many attempts from your connection — try again in about an hour." => "יותר מדי ניסיונות מהחיבור שלכם – נסו שוב בעוד כשעה.",
		"Too many attempts — try again in a few minutes." => "יותר מדי ניסיונות — נסו שוב בעוד כמה דקות.",
		"Too many attempts — try again in about an hour." => "יותר מדי ניסיונות — נסו שוב בעוד כשעה.",
		"Too many tries — ask for a new code." => "יותר מדי ניסיונות — בקשו קוד חדש.",
		"Tools → Export / Erase personal data" => "כלים ← ייצוא / מחיקת מידע אישי",
		"Top bar" => "הדר עליון",
		"Top bar background" => "צבע רקע הדר עליון",
		"Top bar menu" => "תפריט הדר עליון",
		"Top bar text colour" => "צבע טקסט הדר עליון",
		"Top corners (px)" => "פינות עליונות (פיקסלים)",
		"Top, at the side" => "למעלה, בצד",
		"Top, reading side" => "למעלה, צד הקריאה",
		"Total" => "סה״כ",
		"Total units" => "סך כל היחידות",
		"Touching" => "צמוד",
		"Tracking is on" => "המעקב פועל",
		"Transparent header over the content" => "הדר שקוף מעל התוכן",
		"Transparent-header logo (usually the light one)" => "הלוגו של ההדר השקוף (בדרך כלל הבהיר)",
		"Treat them like any other product" => "להתייחס אליהם כמו לכל מוצר אחר",
		"Truly similar — the category, the name, the price, the tags" => "באמת דומים — הקטגוריה, השם, המחיר, התגיות",
		"Truly similar: categories, name, price, tags and attributes" => "דומים באמת: קטגוריות, שם, מחיר, תגיות ומאפיינים",
		"Try a shorter word, or one of these:" => "נסו מילה קצרה יותר, או אחד מאלה:",
		"Try the closest word the shop actually has" => "לנסות את המילה הקרובה ביותר שקיימת בחנות",
		"Tuesday" => "שלישי",
		"Turn selected off" => "כיבוי המסומנים",
		"Turn selected on" => "הפעלת המסומנים",
		"Turn this off in a shop with no branches and the screen steps out of the menu. Nothing is deleted: the branch pages that exist keep working, and the branches block stays available — it is just as useful for \"where to find our products\"." => "בחנות בלי סניפים אפשר לכבות, והמסך יוצא מהתפריט. שום דבר לא נמחק: עמודי הסניפים הקיימים ממשיכים לעבוד, והבלוק של הסניפים נשאר זמין — הוא מתאים בדיוק באותה מידה ל״איפה אפשר למצוא את המוצרים שלנו״.",
		"Turning it off hides the screen and the question — it deletes nothing. The branches you have keep their pages, and the branches block goes on working, which makes it just as useful for \"where to find our products\"." => "כיבוי מסתיר את המסך ואת השאלה — הוא לא מוחק כלום. הסניפים הקיימים שומרים על העמודים שלהם, והבלוק של הסניפים ממשיך לעבוד — מה שהופך אותו מתאים בדיוק באותה מידה ל״איפה אפשר למצוא את המוצרים שלנו״.",
		"Turnstile" => "Turnstile",
		"Turnstile active" => "Turnstile פעיל",
		"Twitter card type" => "סוג כרטיס טוויטר",
		"Twitter description" => "תיאור טוויטר",
		"Twitter image" => "תמונת טוויטר",
		"Twitter title" => "כותרת טוויטר",
		"Twitter: image / title / description (falls back to the share values)" => "טוויטר: תמונה / כותרת / תיאור (נופל לערכי השיתוף)",
		"Two across" => "שני טורים",
		"Two by two" => "שניים על שניים",
		"Two columns fold back into one on a phone." => "במובייל שתי העמודות מתקפלות לאחת.",
		"Two columns — greeting and summary on one side" => "שתי עמודות — הברכה והסיכום בצד אחד",
		"Two columns — greeting and summary on one side, the rest beside them" => "שתי עמודות — הברכה והסיכום בצד אחד, השאר לצידם",
		"Two different things, and the drawing beside you shows both. A choice is something the buyer picks before buying — a colour, a size. A detail is something the product simply has, and it sits in a table further down." => "שני דברים שונים, והסקיצה לצידכם מראה את שניהם. בחירה היא משהו שהקונה בוחר לפני הקנייה — צבע, מידה. פרט הוא משהו שלמוצר פשוט יש, והוא יושב בטבלה נמוך יותר.",
		"Two dropdowns side by side" => "שני דרופ-דאונים זה לצד זה",
		"Two per row" => "שתיים בשורה",
		"Two pictures, staggered" => "שתי תמונות במדורג",
		"Two pictures, the next one peeking" => "שתי תמונות — הבאה מציצה",
		"Two pixels up, nothing else" => "שני פיקסלים למעלה, שום דבר נוסף",
		"Two products and a peek" => "שני מוצרים והצצה",
		"Two products were bought together in %d orders, and are not a bundle" => "שני מוצרים נקנו יחד ב‑%d הזמנות, ואינם מוגדרים כחבילה",
		"Two ways the menu can meet the picture under it. Which one do you like more?" => "שתי דרכים שבהן התפריט נפגש עם התמונה שמתחתיו. לאיזו מהן אתם מתחברים יותר?",
		"Two — a link and its children" => "שתיים — קישור ותתי הקישורים שלו",
		"Two — big pictures" => "שניים — תמונות גדולות",
		"Two-column file" => "קובץ שתי עמודות",
		"Two-column grid" => "רשת דו-טורית",
		"Two-step sign-in" => "אימות דו-שלבי",
		"Two-step sign-in for staff" => "אימות דו-שלבי לצוות",
		"Two-step sign-in is currently off for everyone. The number is kept ready for when it is switched on." => "אימות דו-שלבי כבוי כרגע לכולם. המספר נשמר ומוכן למקרה שיופעל.",
		"Two-step sign-in is on, but there is no phone number on your account — so there is nowhere to send your code and your account is still protected by its password alone. Add a mobile number to your profile." => "אימות דו-שלבי מופעל, אבל אין מספר טלפון בחשבון שלך — כך שאין לאן לשלוח את הקוד, והחשבון שלך עדיין מוגן בסיסמא בלבד. הוסף מספר נייד לפרופיל שלך.",
		"Type" => "סוג",
		"Type the code you received." => "הקלידו את הקוד שקיבלתם.",
		"Type the phone number first." => "הקלידו קודם את מספר הטלפון.",
		"Type to find a category…" => "הקלידו כדי למצוא קטגוריה…",
		"Under Add to cart — first message" => "מתחת להוספה לסל — מסר ראשון",
		"Under Add to cart — fourth message" => "מתחת להוספה לסל — מסר רביעי",
		"Under Add to cart — second message" => "מתחת להוספה לסל — מסר שני",
		"Under Add to cart — third message" => "מתחת להוספה לסל — מסר שלישי",
		"Under it" => "מתחתיה",
		"Under the button" => "מתחת לכפתור",
		"Under the buy button" => "מתחת לכפתור הקנייה",
		"Under the buying reasons, in the buying column" => "מתחת למחזקי הקנייה, בתוך עמודת הקנייה",
		"Under the cursor" => "מתחת לסמן",
		"Under the description" => "מתחת לתיאור",
		"Under the gallery" => "מתחת לגלריה",
		"Under the gallery and details" => "מתחת לגלריה ולפרטי המוצר",
		"Under the heading and the price" => "מתחת לכותרת ולמחיר",
		"Under the heading, beside the price" => "מתחת לכותרת, לצד המחיר",
		"Under the icons below add-to-cart" => "מתחת לאייקונים שמתחת להוספה לסל",
		"Under the link itself" => "מתחת לקישור עצמו",
		"Under the picture" => "מתחת לתמונה",
		"Under the pictures" => "מתחת לתמונות",
		"Under the products" => "מתחת למוצרים",
		"Under the tabs (after the upsells)" => "מתחת לטאבים (אחרי האפסייל)",
		"Under the thank-you message, so a customer with a question does not have to look for you." => "מתחת להודעת התודה, כדי שלקוח עם שאלה לא יצטרך לחפש אתכם.",
		"Under the title" => "מתחת לכותרת",
		"Undo batch" => "ביטול אצווה",
		"Uniform" => "אחיד (חיתוך מהמרכז)",
		"Uniform height (px)" => "גובה אחיד (px)",
		"Uniform height — mobile (px, 0 = auto)" => "גובה אחיד — מובייל (px, ‏0 = אוטומטי)",
		"Units" => "יחידות",
		"Unknown menu item." => "פריט תפריט לא מוכר.",
		"Up and down" => "למעלה–למטה",
		"Up to %s" => "עד %s",
		"Up to 1 year" => "עד שנה",
		"Up to 11 characters — the carrier's rule; anything longer is refused." => "עד 11 תווים — מגבלת המפעילים; ארוך יותר נדחה.",
		"Up to 12 payments, no interest" => "עד 12 תשלומים ללא ריבית",
		"Up to 13 months" => "עד 13 חודשים",
		"Up to 2 years" => "עד שנתיים",
		"Up to 3 months" => "עד 3 חודשים",
		"Up to 7 working days, free over 400 ILS" => "עד 7 ימי עסקים, חינם מעל ₪400",
		"Up to how many" => "עד כמה",
		"Up to price" => "עד מחיר",
		"Update" => "עדכון",
		"Update stock" => "עדכון מלאי",
		"Update the target of existing rules" => "עדכון היעד של כללים קיימים",
		"Updated just now" => "עודכן עכשיו",
		"Upgrades" => "שדרוגים",
		"Upgrades background" => "רקע אזור שדרוגים",
		"Upgrades title" => "כותרת שדרוגים",
		"Upload and preview" => "העלאה ותצוגה מקדימה",
		"Upload my own" => "העלאה של שלי",
		"Upload only the old site's addresses — a CSV/XLSX with a URL column (extra columns like name, SKU and type sharpen the match), a sitemap.xml, or a pasted list. Every address walks the matching ladder and comes back with a proposed target and a confidence level. Nothing is written before your approval." => "מעלים רק את כתובות האתר הישן — CSV/XLSX עם עמודת כתובת (עמודות נוספות כמו שם, מק\"ט וסוג מחדדות את ההתאמה), sitemap.xml או רשימה מודבקת. כל כתובת עוברת את סולם ההתאמה וחוזרת עם יעד מוצע ורמת ביטחון. שום דבר לא נכתב לפני האישור שלכם.",
		"Upload the best one you have today — the widest, 1920 pixels across or more. You can always change it later." => "העלו את הטובה ביותר שיש לכם היום — הרחבה ביותר, 1920 פיקסלים לרוחב ומעלה. תמיד אפשר להחליף אותה בהמשך.",
		"Uploaded font — bold" => "פונט שהועלה — מודגש",
		"Uploaded font — medium" => "פונט שהועלה — בינוני",
		"Uploaded font — name" => "פונט שהועלה — שם",
		"Uploaded font — regular" => "פונט שהועלה — רגיל",
		"Uploaded to a product or page that was never published. Removing them empties those drafts." => "הועלו למוצר או לעמוד שמעולם לא פורסם. מחיקה תרוקן את הטיוטות האלה.",
		"Uploaded to something already in the bin. If you might restore it, keep these." => "הועלו לפריט שכבר נמצא באשפה. אם יתכן שתשחזר אותו — כדאי לשמור.",
		"Uploading…" => "מעלה…",
		"Upright" => "לגובה",
		"Upsell background" => "רקע ההמלצות",
		"Upsells" => "מוצרים מוצעים",
		"Upsells in the panel" => "מוצרים מוצעים בפאנל",
		"Use as my default address" => "השתמש בכתובת זו כברירת מחדל",
		"Use the ready-made wording you prepared" => "להשתמש בנוסח המוכן שהכנתם",
		"Use the template" => "שימוש בטמפלט",
		"Used instead of the heading above when the order is being collected rather than delivered." => "מוצגת במקום הכותרת שלמעלה כשההזמנה נאספת ולא נשלחת.",
		"Used on phones. If empty, the desktop image is used." => "לשימוש בטלפון. אם ריק, נעשה שימוש בתמונת הדסקטופ.",
		"Used only by drafts" => "בשימוש רק בטיוטות",
		"Used only by trashed items" => "בשימוש רק בפריטים שבפח",
		"Used when \"from a category\" is picked above." => "בשימוש כשנבחר למעלה ״מקטגוריה״.",
		"Used when \"the ones I choose\" is picked above. Search by name." => "בשימוש כשנבחר למעלה ״אלה שאני בוחר״. חיפוש לפי שם.",
		"Used when a page has no image of its own — a full URL or a media library id." => "משמשת כשלעמוד אין תמונה משלו — כתובת מלאה או מזהה מספריית המדיה.",
		"User name" => "שם משתמש",
		"Username" => "שם משתמש",
		"Usually Monday does this when the site is cloned. Do it here when it did not, or to replace the link. The answers already given stay." => "בדרך כלל Monday עושה את זה כשהאתר משוכפל. עשו את זה כאן כשזה לא קרה, או כדי להחליף את הקישור. התשובות שכבר ניתנו נשארות.",
		"Usually the light version. Swaps back to the regular logo once the page scrolls." => "בדרך כלל הגרסה הבהירה. מתחלף חזרה ללוגו הרגיל ברגע שהעמוד נגלל.",
		"Valid for" => "בתוקף ל",
		"Valid for %s days. See you soon!" => "בתוקף ל-%s ימים. נתראה בקרוב!",
		"Value names beside swatches" => "שמות הערכים ליד הסוואטשים",
		"Value names beside swatches on mobile" => "שמות הערכים ליד הסוואטשים במובייל",
		"Values with no products" => "ערכים ללא מוצרים",
		"Values with no results" => "ערכים בלי תוצאות",
		"Varela Round (headings)" => "Varela Round (לכותרות)",
		"Variation" => "וריאציה",
		"Version" => "גרסה",
		"Video" => "וידאו",
		"Video start and complete" => "התחלת וסיום וידאו",
		"View" => "צפייה",
		"View cart" => "לצפייה בעגלה",
		"View product" => "לצפייה במוצר",
		"View results" => "הצגת תוצאות",
		"View the heat map" => "צפייה במפת חום",
		"View your order" => "לצפייה בהזמנה",
		"Viewed %1\$d times in the last 30 days. At its usual pace, restocking is worth about %2\$s a month." => "נצפה %1\$d פעמים ב‑30 הימים האחרונים. בקצב הרגיל שלו, חידוש מלאי שווה כ‑%2\$s בחודש.",
		"Viewed a product" => "צפו במוצר",
		"Views" => "צפיות",
		"Visible thumbnails (arrows page the rest)" => "ממוזערות מוצגות (חצים מדפדפים בשאר)",
		"Visits" => "כניסות",
		"Visits are counted from the day the statistics were switched on; earlier days show orders only." => "כניסות נספרות מהיום שבו הופעלה הסטטיסטיקה; ימים מוקדמים יותר מציגים הזמנות בלבד.",
		"Visits have been counted since %s; orders before that date are counted, their visits are not — so the funnel and the rates are only complete from that date on." => "הכניסות נספרות מ־%s. הזמנות מלפני התאריך הזה נספרות, אבל הכניסות שלהן לא, ולכן המשפך ויחסי ההמרה מלאים רק מהתאריך הזה והלאה.",
		"Visits that bought" => "ביקורים שקנו",
		"Visits to the category fell too — fewer people reach it. Worth a place on the home page or in the menu." => "גם הכניסות לקטגוריה ירדו – פחות אנשים מגיעים אליה. שווה מקום בדף הבית או בתפריט.",
		"Visits to the category held; the drop is inside it — stock that ran out, a price that changed, or a lead product that fell off the first row." => "הכניסות לקטגוריה נשמרו; הירידה היא בתוכה – מלאי שאזל, מחיר שהשתנה, או מוצר מוביל שירד מהשורה הראשונה.",
		"WP All Import keys" => "מפתחות WP All Import",
		"Wait before loading it anyway (milliseconds)" => "המתנה לפני טעינה בכל מקרה (מילישניות)",
		"Waiting" => "ממתינים",
		"Waiting for the customer" => "ממתין ללקוח",
		"Want to follow us?" => "רוצה לעקוב אחרינו?",
		"Warranty" => "אחריות",
		"We are here — whichever way suits you." => "אנחנו כאן, בכל דרך שנוחה לך.",
		"We are putting the finishing touches on the new store. Come back soon." => "אנחנו נותנים את הנגיעות האחרונות בחנות החדשה. חזרו אלינו בקרוב.",
		"We are starting on your new store. The first step is a short questionnaire about your business, your pages and how you would like things to look." => "אנחנו יוצאים לדרך עם החנות החדשה שלכם. הצעד הראשון הוא שאלון קצר על העסק, על העמודים ועל איך תרצו שהדברים ייראו.",
		"We could not file that request. Check the address and try again, or write to us directly." => "לא הצלחנו לרשום את הבקשה. בדקו את הכתובת ונסו שוב, או כתבו לנו ישירות.",
		"We could not find \"%1\$s\" — showing results for \"%2\$s\"." => "לא מצאנו את ״%1\$s״ — מציגים תוצאות עבור ״%2\$s״.",
		"We do not know this number yet — fill in your details once, and next time the phone alone gets you in." => "המספר עדיין לא מוכר לנו — מלאו פרטים פעם אחת, ובפעם הבאה נכנסים עם הטלפון בלבד.",
		"We found these pages on your current site and filled the addresses in. Have a look that they are the right ones." => "מצאנו באתר שלכם את העמודים האלה והזנו את הכתובות. הציצו שאלה העמודים הנכונים.",
		"We found this address on your site. Change it if it is the wrong page." => "מצאנו את הכתובת הזו באתר שלכם. שנו אותה אם זה לא העמוד הנכון.",
		"We go over everything that was built and put the last touches to it." => "אנחנו עוברים על כל מה שנבנה ונותנים לזה את הנגיעות האחרונות.",
		"We go over everything that was built, load your products once you have them ready, and go over the site with you before it goes live." => "אנחנו עוברים על כל מה שנבנה, מעלים את המוצרים ברגע שהם מוכנים, ועוברים איתכם על האתר לפני שהוא עולה לאוויר.",
		"We go over your answers and set up the shell of the site." => "אנחנו עוברים על התשובות שלכם ומקימים את שלד האתר.",
		"We got it — your site is being built" => "קיבלנו — האתר שלכם בבנייה",
		"We have received your order and we are already getting it ready.\nIt is expected to reach you between [from] and [to].\nWe will email you again the moment it leaves us, so you know exactly where it is." => "קיבלנו את ההזמנה שלך ואנחנו כבר מכינים אותה.\nהיא צפויה להגיע אליך בין [from] ל־[to].\nנעדכן אותך במייל ברגע שהיא יוצאת לדרך, כדי שתדע בדיוק איפה היא.",
		"We have received your order and we are already getting it ready.\nWe will email you the moment it is waiting for you at the branch.\nEverything you ordered is listed below." => "קיבלנו את ההזמנה שלך ואנחנו כבר מכינים אותה.\nנעדכן אותך במייל ברגע שהיא מחכה לך בסניף.\nכל מה שהזמנת מופיע למטה.",
		"We have refunded your order.\nThe money goes back the way it was paid, and it usually takes a few working days to show up.\nThe amount and the order are below." => "ביצענו החזר עבור ההזמנה שלך.\nהכסף חוזר באותו אמצעי שבו שולם, ובדרך כלל לוקח כמה ימי עסקים עד שהוא מופיע.\nהסכום ופרטי ההזמנה מופיעים למטה.",
		"We have your order, and it is waiting for the payment to come through.\nThe moment it does we will get it ready and email you when it is waiting at the branch.\nEverything you ordered is listed below." => "ההזמנה שלך אצלנו, והיא ממתינה לאישור התשלום.\nברגע שהוא יתקבל נכין אותה ונעדכן אותך במייל כשהיא מחכה לך בסניף.\nכל מה שהזמנת מופיע למטה.",
		"We have your order, and it is waiting for the payment to come through.\nThe moment it does we will start getting it ready and email you again.\nEverything you ordered is listed below." => "ההזמנה שלך אצלנו, והיא ממתינה לאישור התשלום.\nברגע שהוא יתקבל נתחיל להכין אותה ונעדכן אותך במייל.\nכל מה שהזמנת מופיע למטה.",
		"We load your products once you have them ready." => "אנחנו מעלים את המוצרים שלכם ברגע שהם מוכנים.",
		"We open it with a short text drawn from your terms. You can rewrite it whenever you like." => "נפתח אותה בטקסט קצר ברוח התקנון שלכם. אפשר לשכתב אותו מתי שתרצו.",
		"We sent a code to the phone ending %s." => "שלחנו קוד לטלפון שמסתיים ב-%s.",
		"We show the links to your social profiles and invite the buyer to follow you." => "נציג את הקישורים לרשתות החברתיות שלכם ונעודד את הקונה לעקוב אחריכם.",
		"We use cookies to run the shop, measure visits and show relevant offers." => "אנחנו משתמשים בעוגיות כדי להפעיל את החנות, למדוד ביקורים ולהציג הצעות רלוונטיות.",
		"We use cookies to run the shop, to understand how it is used and to show you relevant offers. You choose what to allow, and you can change your mind at any time." => "אנחנו משתמשים בעוגיות כדי להפעיל את החנות, להבין איך משתמשים בה ולהציג לך הצעות רלוונטיות. אתם בוחרים מה לאפשר, ואפשר לשנות את הבחירה בכל עת.",
		"We will bring the content over from there. The questionnaire does not wait for it — fill it in and we do the rest." => "אנחנו נעביר משם את התוכן. השאלון לא מחכה לזה — מלאו אותו ואנחנו נעשה את השאר.",
		"WebP is the same picture at about a quarter of the weight. Every browser in use reads it." => "WebP הוא אותה תמונה בערך ברבע מהמשקל. כל הדפדפנים בשימוש קוראים אותו.",
		"Wednesday" => "רביעי",
		"Weekly report" => "דוח שבועי",
		"Weight" => "עובי",
		"Welcome to [shop]" => "ברוך הבא ל־[shop]",
		"What a courier to the door costs" => "כמה עולה שליח עד הבית",
		"What a product card carries" => "מה מופיע על כרטיס המוצר",
		"What already follows the choice" => "מה כבר פועל לפי הבחירה",
		"What are they called?" => "איך הם נקראים?",
		"What can be bought stands first, and what cannot waits at the back instead of taking the good places." => "מה שאפשר לקנות עומד ראשון, ומה שאי אפשר מחכה מאחור במקום לתפוס את המקומות הטובים.",
		"What customers paid, including shipping and VAT, for paid orders and orders in hand." => "מה שהלקוחות שילמו, כולל משלוח ומע״מ, בהזמנות ששולמו ובטיפול.",
		"What did not become sales" => "מה לא הפך למכירה",
		"What else can they pay with?" => "באילו אמצעים נוספים אפשר לשלם?",
		"What else the page offers" => "מה עוד יופיע בעמוד",
		"What else the page offers after the product itself. Four things, each with its own job — the drawing shows where each lands." => "מה עוד העמוד מציע אחרי המוצר עצמו. ארבעה דברים, לכל אחד תפקיד משלו — הסקיצה מראה איפה כל אחד נוחת.",
		"What else the page tells" => "מה עוד העמוד מספר",
		"What happens now" => "מה קורה עכשיו",
		"What happens under the cursor" => "מה קורה מתחת לסמן",
		"What is left for you" => "מה נשאר אצלכם",
		"What is recorded" => "מה נרשם",
		"What is this block?" => "מה הבלוק הזה?",
		"What it costs to send, whether people can come and collect, and who takes the money. No drawing here — none of it shows on a page." => "כמה עולה לשלוח, האם אפשר לבוא לאסוף, ומי לוקח את הכסף. אין כאן סקיצה — שום דבר מזה לא מופיע על עמוד.",
		"What it is called" => "איך היא נקראת",
		"What it lists" => "מה מוצג בו",
		"What it says" => "מה כתוב בו",
		"What kind of store?" => "איזה סוג חנות?",
		"What must be filled in besides the street?" => "מה חובה למלא מלבד הרחוב?",
		"What people ask you before they buy. Leave an answer empty and the question waits for you in the editor." => "מה שואלים אתכם לפני שקונים. אפשר להשאיר תשובה ריקה והשאלה תחכה לכם בעורך.",
		"What people search for" => "מה מחפשים",
		"What people search for most" => "מה שהכי מחפשים",
		"What separates it from the header." => "מה שמפריד בינו לבין ההדר.",
		"What separates it from the page." => "מה שמפריד בינו לבין תוכן העמוד.",
		"What stands above the products?" => "מה עומד מעל המוצרים?",
		"What stands in the banner?" => "מה עומד בבאנר?",
		"What stands on the home page" => "מה עומד בדף הבית",
		"What the button says" => "הטקסט על הכפתור",
		"What the colours mean" => "מה הצבעים אומרים",
		"What the customer sees right after paying." => "מה הלקוח רואה מיד אחרי התשלום.",
		"What the image says, for screen readers." => "מה שהתמונה אומרת, עבור קוראי מסך.",
		"What the tab is called" => "איך הלשונית נקראת",
		"What the tab says" => "מה כתוב בלשונית",
		"What to call it at the checkout" => "איך זה ייקרא בקופה",
		"What to do now" => "מה כדאי לעשות עכשיו",
		"What we sell" => "מה אנחנו מוכרים",
		"What will be in the main banner?" => "מה יהיה בבאנר הראשי?",
		"What would you like to say?" => "מה תרצו להגיד?",
		"Whatever each product in the cart recommends" => "מה שכל מוצר שבסל ממליץ עליו",
		"Whatever is on offer" => "מה שבמבצע",
		"Whatever is ticked is added together with the product itself." => "כל מה שמסומן יתווסף לסל יחד עם המוצר עצמו.",
		"Whatever suits the picture" => "לפי התמונה",
		"WhatsApp" => "וואטסאפ",
		"WhatsApp and email" => "וואטסאפ וגם אימייל",
		"WhatsApp group" => "קבוצת וואטסאפ",
		"WhatsApp group invite link" => "קישור הזמנה לקבוצת וואטסאפ",
		"WhatsApp message" => "הודעת וואטסאפ",
		"WhatsApp number" => "מספר וואטסאפ",
		"WhatsApp sender number" => "מספר השולח בוואטסאפ",
		"WhatsApp:" => "וואטסאפ:",
		"When" => "מתי",
		"When \"place order\" is pressed, WooCommerce creates an unpaid order and holds its stock for a while. A shopper who comes back from the payment page to add something to the cart is still holding that stock through their own order, and with one unit left WooCommerce refuses the new order: \"not enough in stock\". With this on, the earlier unpaid order of the same shopper is cancelled quietly (no e-mail) the moment the new one is created, and its hold is released. Works with every payment method, since it happens before payment." => "בלחיצה על \"שליחת הזמנה\" ווקומרס יוצר הזמנה שלא שולמה ומשריין לה מלאי לזמן מוגבל. לקוח שחוזר מעמוד התשלום כדי להוסיף משהו לסל עדיין מחזיק את המלאי הזה דרך ההזמנה שלו עצמו, וכשנשארה יחידה אחת ווקומרס מסרב להזמנה החדשה: \"אין מספיק במלאי\". כשזה פעיל, ההזמנה הקודמת שלא שולמה של אותו לקוח מבוטלת בשקט (בלי מייל) ברגע שהחדשה נוצרת, והשריון שלה משתחרר. עובד עם כל שיטת תשלום, כי זה קורה לפני התשלום.",
		"When nothing matches" => "כשאין תוצאות",
		"When several prices apply" => "כשכמה מחירים חלים",
		"When the picture is taller than the tile it fills, this decides which part stays: 0 keeps the top (a head, a hat), 100 keeps the bottom." => "כשהתמונה גבוהה מהאריח שהיא ממלאת, זה קובע איזה חלק נשאר: 0 שומר על החלק העליון (ראש, כובע), 100 על החלק התחתון.",
		"When the search opens" => "כשהחיפוש נפתח",
		"Where" => "היכן",
		"Where do the small pictures sit?" => "איפה יושבות התמונות הקטנות?",
		"Where do they sit?" => "איפה הם יושבים?",
		"Where do they stand?" => "איפה הם עומדים?",
		"Where does the button lead?" => "לאיזה עמוד הכפתור מוביל?",
		"Where does the filter sit?" => "איפה יושב הסינון?",
		"Where does the menu sit over the banner?" => "איפה יושב התפריט ביחס לבאנר?",
		"Where does the menu stand over the banner?" => "איפה עומד התפריט מעל הבאנר?",
		"Where does the short description go?" => "איפה יושב התיאור הקצר?",
		"Where it is used" => "איפה בשימוש",
		"Where orders came from" => "מאיפה הגיעו ההזמנות",
		"Where people look, and where they click. Only the pages below are recorded, and the visitor pays nothing for it: the marks are counted in the browser and sent once, as the page closes." => "איפה מסתכלים ואיפה לוחצים. רק העמודים שלמטה נרשמים, והגולש לא משלם על זה כלום: הסימונים נספרים בדפדפן ונשלחים פעם אחת, כשהעמוד נסגר.",
		"Where shoppers drop off" => "איפה הקונים נוטשים",
		"Where should new-order notices go?" => "לאיזה מייל לשלוח עדכון על הזמנה חדשה?",
		"Where should the accessibility statement come from?" => "מאיפה ניקח את הצהרת הנגישות?",
		"Where should the privacy policy come from?" => "מאיפה ניקח את מדיניות הפרטיות?",
		"Where should the terms come from?" => "מאיפה ניקח את התקנון?",
		"Where the decision is made. The pictures on one side, everything the buyer needs on the other." => "כאן מתקבלת ההחלטה. התמונות בצד אחד, וכל מה שהקונה צריך בצד השני.",
		"Where the decision is made. The pictures on one side, everything the buyer needs on the other. Every answer here changes the drawing beside you." => "כאן מתקבלת ההחלטה. התמונות בצד אחד, וכל מה שהקונה צריך בצד השני. כל תשובה כאן משנה את הסקיצה שלצידכם.",
		"Where the face sits in the circle (0 = top, 100 = bottom)" => "איפה הפנים יושבות בעיגול (0 = למעלה, 100 = למטה)",
		"Where the logo and the menu stand" => "איפה עומדים הלוגו והתפריט",
		"Where the panel opens from, its width, the footer buttons and the upsell placement are set in %s." => "מהיכן המגירה נפתחת, רוחבה, כפתורי התחתית ומיקום ההמלצות — נקבעים ב%s.",
		"Where the row lines up — also inside the banner. “Follow the text” keeps it with the banner’s words, or with the page title when it stands above the products." => "איפה השורה מתיישרת — גם בתוך הבאנר. ״לפי הטקסט״ מיישר אותה עם הטקסט של הבאנר, או עם כותרת העמוד כשהיא מעל המוצרים.",
		"Where the words sit" => "מיקום הטקסט",
		"Where they appear" => "היכן מוצגות",
		"Where they came from" => "מאיפה הגיעו",
		"Where this link appears" => "היכן הקישור מופיע",
		"Where to look" => "איפה מחפשים",
		"Whether filtering is on, its layout and how values are presented are set in %s." => "הפעלת הסינון, הפריסה שלו ואופן הצגת הערכים — נקבעים ב%s.",
		"Which branches can be collected from" => "מאילו סניפים אפשר לאסוף",
		"Which brands" => "אילו מותגים",
		"Which built-in tabs appear, and in what order, is set in %s." => "אילו טאבים מובנים מוצגים ובאיזה סדר — נקבע ב%s.",
		"Which category" => "איזו קטגוריה",
		"Which days do orders go out?" => "באילו ימים יוצאות ההזמנות?",
		"Which of its products" => "אילו מהמוצרים שלה",
		"Which of them stand on the home page" => "אילו מהן יעמדו בעמוד הבית",
		"Which one" => "איזו",
		"Which part the frame keeps when it has to crop: 0 the top, 50 the middle, 100 the bottom." => "איזה חלק המסגרת שומרת כשהיא נאלצת לחתוך: 0 החלק העליון, 50 האמצע, 100 התחתון.",
		"Which pictures and films weigh the most, and which pages they sit on. A heavy file is not a mistake — it is simply what every visitor to that page downloads." => "אילו תמונות וסרטונים שוקלים הכי הרבה, ובאילו עמודים הם יושבים. קובץ כבד אינו טעות — הוא פשוט מה שכל מבקר בעמוד הזה מוריד.",
		"Which products" => "אילו מוצרים",
		"Which products are offered?" => "אילו מוצרים מוצעים?",
		"Which products count as similar" => "אילו מוצרים נחשבים דומים",
		"Which products?" => "אילו מוצרים?",
		"Which side are the pictures on?" => "באיזה צד התמונות?",
		"Which side does the cart slide out from?" => "מאיזה צד נפתחת חלונית הסל?",
		"While the site is being built" => "בזמן שהאתר בהקמה",
		"While you are searching, the order cannot be changed. Clear the box to go back to it." => "בזמן חיפוש אי אפשר לשנות את הסדר. נקו את תיבת החיפוש כדי לחזור אליו.",
		"White" => "לבן",
		"Who answers" => "מי עונה",
		"Who are we talking to" => "עם מי אנחנו מדברים",
		"Who clears your card payments?" => "מי מסלק לכם את התשלומים בכרטיס?",
		"Who is it for?" => "למי הפיד?",
		"Who it goes to" => "למי זה הולך",
		"Who we call about the site, where the reminders go, and the name on the record of the wording you approve on the next screen. Usually already filled in — just check it." => "למי אנחנו מתקשרים בענייני האתר, לאן נשלחות התזכורות, ומי השם שנרשם באישור הנוסחים במסך הבא. בדרך כלל כבר מלא — רק לוודא.",
		"Whole keeps every product photo complete inside the box, with a quiet ground where its proportions differ from the ratio above." => "שלמה שומרת כל תמונת מוצר שלמה בתוך התיבה, עם רקע שקט היכן שהיחס שלה שונה מהיחס שלמעלה.",
		"Whole library" => "כל הספרייה",
		"Whole site" => "כל האתר",
		"Whole, never cropped" => "שלמה, בלי חיתוך",
		"Wide" => "רחב",
		"Wide content" => "תוכן רחב",
		"Wide gallery" => "גלריה רחבה",
		"Wide picture, small guest" => "תמונה רחבה ואורחת קטנה",
		"Wide tile" => "אריח רחב",
		"Wide tile — every" => "אריח רחב — כל",
		"Wide — 2 columns" => "רחב — 2 עמודות",
		"Wide, with the words" => "רחב, עם הטקסט",
		"Width" => "רוחב",
		"Width (px)" => "רוחב (פיקסלים)",
		"With a buy button on the card" => "עם כפתור קנייה על הכרטיס",
		"With a comment, last 30 days" => "עם מילים, 30 יום אחרונים",
		"With more than one we build a branches page: every branch gets its own page with its address, hours and a map, and customers can pick one for collection at the checkout." => "כשיש יותר מאחד אנחנו בונים עמוד סניפים: לכל סניף עמוד משלו עם הכתובת, השעות ומפה, והלקוחות יכולים לבחור סניף לאיסוף בקופה.",
		"With the text, under the description" => "יחד עם הטקסט, מתחת לתיאור",
		"With you" => "אצלך",
		"Without a number there is nowhere to send a code, so this account still rests on its password alone." => "בלי מספר אין לאן לשלוח קוד, ולכן החשבון הזה עדיין מוגן בסיסמא בלבד.",
		"WooCommerce cart and session cookies, sign-in — necessary, always on." => "עוגיות הסל וה-session של WooCommerce, התחברות - הכרחיות, תמיד פעילות.",
		"WooCommerce holds stock for %1\$d minutes per unpaid order (%2\$s)." => "ווקומרס משריין מלאי למשך %1\$d דקות לכל הזמנה שלא שולמה (%2\$s).",
		"WooCommerce is not active on this site yet." => "ווקומרס עדיין לא פעיל באתר הזה.",
		"WooCommerce prices delivery again; %d of its methods were switched back on." => "ווקומרס מתמחרת שוב את המשלוח; %d משיטותיה הופעלו מחדש.",
		"WooCommerce would not add the method." => "ווקומרס לא הוסיף את שיטת המשלוח.",
		"WooCommerce → Settings → Products → Inventory" => "ווקומרס ← הגדרות ← מוצרים ← מלאי",
		"WooCommerce's own catalogue settings, and the theme's on top of them." => "הגדרות הקטלוג של ווקומרס עצמו, ושל התבנית מעליהן.",
		"WordPress did not produce a WebP file." => "וורדפרס לא יצר קובץ WebP.",
		"WordPress reviews never render as a tab — a dedicated mechanism replaces them." => "חוות הדעת של וורדפרס לא מוצגות כטאב — מנגנון ייעודי יחליף אותן.",
		"Wording" => "נוסח",
		"Words" => "טקסט",
		"Words and two pictures" => "טקסט ושתי תמונות",
		"Words held" => "מילים שמורות",
		"Words separated by commas — a nickname, a former name, the English spelling." => "מילים מופרדות בפסיקים — כינוי, שם קודם, או הכתיב הלועזי.",
		"Words separated by commas. A shopper who types any of them finds everything carrying this one — so on the colour red, write: אדומה, אדומים, אדומות." => "מילים מופרדות בפסיקים. מי שיקליד אחת מהן ימצא את כל מה שנושא את הערך הזה — למשל על הצבע אדום, כתבו: אדומה, אדומים, אדומות.",
		"Words that mean the same thing" => "מילים שמשמעותן זהה",
		"Words that stay while the pictures move" => "תוכן סטיקי — הטקסט נשאר והתמונות זזות",
		"Words, a picture, and a film over it" => "טקסט, תמונה וסרטון עליה",
		"Worked out from your address" => "מחושב לפי הכתובת",
		"Working…" => "עובד…",
		"Worth doing now" => "כדאי לעשות עכשיו",
		"Worth it when people buy several of the same thing. A buyer can change the quantity in the cart either way." => "שווה כשקונים כמה יחידות מאותו דבר. בכל מקרה אפשר לשנות כמות בעגלה.",
		"Wrapped rows" => "שורות שנשברות",
		"Write a privacy policy page for this site" => "כתיבת עמוד מדיניות פרטיות לאתר הזה",
		"Write here how long it takes and from what amount it is free." => "כתבו כאן כמה זמן זה לוקח ומאיזה סכום המשלוח חינם.",
		"Write it for me from a few points" => "כתבו לי מכמה נקודות",
		"Write something now — it is on the page from the first day, and it can be changed at any time." => "כתבו משהו עכשיו — זה מה שיעמוד בעמוד מהיום הראשון, ותמיד אפשר לשנות.",
		"Write the ALT into the library the moment a file is uploaded" => "קבע את ה-ALT בספרייה ברגע העלאת הקובץ",
		"Write the accessibility statement" => "כתוב הצהרת נגישות",
