		"Written into the chat before the shopper sends. [product] becomes the product name and [link] its address. Empty: \"Hi, I'd like some help with [product] / Link: [link]\"." => "נכתבת בצ׳אט לפני שהלקוח שולח. [product] הופך לשם המוצר ו־[link] לכתובת שלו. אפשר גם [שם המוצר] ו־[קישור]. ריק: ״היי, אני מעוניין לקבל עזרה על מוצר [product] / קישור: [link]״.",
